/* Blackboard lessons for the analytic geometry cheat sheet: one lesson per card.
   Every lesson draws its picture on an equal-scale graph. Texts: 'en|fr|es|ja|zh'. */
(function () {
  const R = String.raw;
  const IDEA = 'The idea|L’idée|La idea|考え方|思路', EX = 'Worked example|Exemple résolu|Ejemplo resuelto|例題|例题', YOUR = 'Your turn|À vous|Te toca|やってみよう|轮到你了';
  const TRY = 'Work it out on paper, type the answer (a fraction or a decimal) and check it. Each hint writes the next line of the solution on the board.|Faites le calcul sur papier, tapez la réponse (fraction ou décimal) et vérifiez. Chaque indice écrit la ligne suivante de la solution au tableau.|Hazlo en papel, escribe la respuesta (fracción o decimal) y compruébala. Cada pista escribe en la pizarra la siguiente línea de la solución.|紙で計算し、答え（分数か小数）を入力して確かめましょう。ヒントごとに解答が 1 行ずつ黒板に書かれます。|先在纸上算，输入答案（分数或小数）并检查。每次提示会在黑板上写出解答的下一行。';
  const F = (tex, o = {}) => ['w', R`\displaystyle ` + tex, Object.assign({ s: 26 }, o)];
  const Y = (tex, o = {}) => F(tex, Object.assign({ c: 'y' }, o));
  const W = (txt, o = {}) => ['t', txt, Object.assign({ s: 18, c: 'b' }, o)];
  const H = name => ['t', name, { head: true, s: 16, c: 'y' }];
  const Z = (x, y) => [x, y, 0];
  // give a group of scene items quick, staggered delays (the default is 300 ms per item, too slow for grids)
  const SEQ = (items, d0 = 200, step = 40) => items.map((a, i) => { const o = a[a.length - 1]; if (o && typeof o === 'object' && !Array.isArray(o)) o.d = d0 + i * step; return a; });
  const S2 = (c, r, axes = false) => ['3d', { flat: true, axes, c: [c[0], c[1], 0], r }];
  const CI = (o, r, c, fill = 0.16) => ['circ3', Z(...o), [0, 0, 1], r, { c, fill }];
  const LB = (p, t, c = 'y', size) => ['lab3', Z(...p), t, Object.assign({ c }, size ? { size } : {})];
  const SG = (p, q, c = 'chalk', o = {}) => ['seg', Z(...p), Z(...q), Object.assign({ c }, o)];
  const PT = (p, lab, c = 'y', o = {}) => ['pt3', Z(...p), lab || '', Object.assign({ c }, o)];
  const RECT = (x0, y0, x1, y1, c = 'b', fill = 0.3) => ['poly3', [Z(x0, y0), Z(x1, y0), Z(x1, y1), Z(x0, y1)], { c, fill }];
  // a Venn diagram of A and B inside the universe
  const VENN = (la = 'A', lb = 'B', extra = []) => [S2([0, 0], 2.2), ...SEQ([RECT(-2.4, -1.6, 2.4, 1.6, 'chalk', 0.03), CI([-0.6, 0], 1.1, 'b'), CI([0.6, 0], 1.1, 'p'), LB([-1.3, 1.1], la, 'b'), LB([1.2, 1.1], lb, 'p'), LB([-2.2, 1.35], 'Ω', 'chalk'), ...extra], 200, 160)];
  // a two-level tree: first branch probability p (labels a, ā), then q1 / q2 for the event on each branch
  const TREE = (p, q1, q2, la, lb) => [S2([1.5, 0], 2.2), ...SEQ([
    SG([0, 0], [1.5, 1.2], 'b'), SG([0, 0], [1.5, -1.2], 'b'), SG([1.5, 1.2], [3, 1.8], 'y'), SG([1.5, 1.2], [3, 0.6], 'chalk'), SG([1.5, -1.2], [3, -0.6], 'y'), SG([1.5, -1.2], [3, -1.8], 'chalk'),
    LB([0.45, 0.85], p, 'b'), LB([0.45, -1.05], '1 − ' + p, 'b'), LB([1.5, 1.4], la[0], 'b'), LB([1.5, -1.0], la[1], 'b'),
    LB([2.0, 1.75], q1, 'y'), LB([2.0, -0.55], q2, 'y'), LB([3.1, 1.8], lb[0], 'y'), LB([3.1, 0.6], lb[1], 'chalk'), LB([3.1, -0.6], lb[0], 'y'), LB([3.1, -1.8], lb[1], 'chalk')], 200, 90)];
  // a bar chart: probabilities p[k] at x = k0 + k (height scaled by s)
  const BARS = (ps, k0 = 0, s = 1, c = 'b', hi = -1) => SEQ(ps.map((p, k) => RECT(k0 + k - 0.38, 0, k0 + k + 0.38, p * s, k === hi ? 'y' : c, k === hi ? 0.55 : 0.3)), 200, 70);
  const AX = (xw, yw) => ['ax', { xw, yw }], P = (eq, c = 'y', o = {}) => ['p', 'y=' + eq, Object.assign({ c }, o)], SH = (a, b) => ['sh', a, b];
  const N01 = 'e^(-x^2/2)/sqrt(2pi)';
  const L = {};
  const lesson = (key, head, idea, ex, your) => {
    L[key] = [{ t: IDEA, s: idea.s, a: [H(head), ...idea.a] }, { t: EX, s: ex.s, a: [['clr'], H(head), ...ex.a] },
      { t: YOUR, s: your.s || TRY, a: [['clr'], H(head), ...(your.a || [])], ex: your.ex }];
  };
  const C = (a, b) => { let r = 1; for (let k = 1; k <= b; k++) r = r * (a - b + k) / k; return r; };
  const binom = (n, p) => [...Array(n + 1)].map((_, k) => C(n, k) * p ** k * (1 - p) ** (n - k));

  const D = (eq, c = 'b') => P(eq, c, { dash: true });
  const VL = (x, y0, y1, c = 'p') => ['ln', x, y0, x, y1, { c, dash: true }];
  const D2 = y => D(y, 'p'), VL2 = x => VL(x, -10, 10);   // directrices
  const EQ = (xw, yw) => ['ax', { xw, yw, eq: true }];
  const IP = (eq, c = 'y', o = {}) => ['p', eq, Object.assign({ c }, o)];          // implicit or explicit curve, written in full
  const SEGL = (x1, y1, x2, y2, c = 'b', o = {}) => ['ln', x1, y1, x2, y2, Object.assign({ c }, o)];
  const PTL = (x, y, lab, c = 'o') => ['pt', x, y, lab, { c }];
  const TRY_P = 'Type the point as (x, y) and check it. Each hint writes the next line of the solution.|Tapez le point sous la forme (x, y) et vérifiez. Chaque indice écrit la ligne suivante.|Escribe el punto como (x, y) y compruébalo. Cada pista escribe la siguiente línea.|点を (x, y) の形で入力して確かめよう。ヒントごとに解答が 1 行ずつ書かれます。|以 (x, y) 形式输入点并检查。每次提示写出下一行。';
  const TRY_E = 'Write the line as y = … (type only the right-hand side, for example 3x - 5) and check it.|Écrivez la droite sous la forme y = … (tapez seulement le membre de droite, par exemple 3x - 5) et vérifiez.|Escribe la recta como y = … (solo el miembro derecho, por ejemplo 3x - 5) y compruébala.|直線を y = … の形で（右辺だけ、例：3x - 5）入力して確かめよう。|把直线写成 y = …（只输入右边，如 3x - 5）并检查。';
  const TRY_R = 'Type all the values separated by ; in any order (for example 2; -3) and check. Each hint writes the next line of the solution.|Tapez toutes les valeurs séparées par ; dans n’importe quel ordre (par exemple 2; -3) et vérifiez. Chaque indice écrit la ligne suivante.|Escribe todos los valores separados por ; en cualquier orden (por ejemplo 2; -3) y comprueba. Cada pista escribe la siguiente línea.|すべての値を ; で区切って順不同で入力（例：2; -3）して確かめよう。ヒントごとに解答が 1 行ずつ書かれます。|输入所有值，用 ; 分隔，顺序不限（如 2; -3），并检查。每次提示写出下一行。';

  // =============================== Points ===============================
  lesson('Points/Distance', 'Distance between two points|Distance entre deux points|Distancia entre dos puntos|2 点間の距離|两点间距离',
    { s: R`Draw the right triangle with horizontal side $\Delta x$ and vertical side $\Delta y$; the segment is its hypotenuse, so Pythagoras gives its length. The order of the points does not matter because the differences are squared.|On dessine le triangle rectangle de côtés horizontal $\Delta x$ et vertical $\Delta y$ ; le segment en est l’hypoténuse, Pythagore donne sa longueur. L’ordre des points n’importe pas car les différences sont au carré.|Dibuja el triángulo rectángulo de cateto horizontal $\Delta x$ y vertical $\Delta y$; el segmento es su hipotenusa, así que Pitágoras da su longitud. El orden de los puntos no importa porque las diferencias van al cuadrado.|横 $\Delta x$、縦 $\Delta y$ の直角三角形を描くと線分は斜辺。三平方の定理で長さが出る。差は 2 乗するので点の順序は関係ない。|画出水平边 $\Delta x$、竖直边 $\Delta y$ 的直角三角形；线段是斜边，由勾股定理得长度。差要平方，所以点的顺序无关。`,
      a: [Y(R`d = \sqrt{(x_2 - x_1)^2 + (y_2 - y_1)^2}`), EQ([-1, 6], [-1, 7]), SEGL(1, 2, 4, 6, 'y'), SEGL(1, 2, 4, 2, 'b', { dash: true }), SEGL(4, 2, 4, 6, 'b', { dash: true }), PTL(1, 2, 'A'), PTL(4, 6, 'B')] },
    { s: R`$A(1, 2)$, $B(4, 6)$: $\Delta x = 3$, $\Delta y = 4$, so $AB = \sqrt{9 + 16} = 5$.|$A(1, 2)$, $B(4, 6)$ : $\Delta x = 3$, $\Delta y = 4$, donc $AB = 5$.|$A(1, 2)$, $B(4, 6)$: $\Delta x = 3$, $\Delta y = 4$, así que $AB = 5$.|$AB = \sqrt{9 + 16} = 5$。|$AB = \sqrt{9 + 16} = 5$。`,
      a: [F(R`\Delta x = 3,\quad \Delta y = 4`), Y(R`AB = \sqrt{9 + 16} = 5`), EQ([-1, 6], [-1, 7]), SEGL(1, 2, 4, 6, 'y'), PTL(1, 2, 'A'), PTL(4, 6, 'B')] },
    { a: [F(R`A(-2, 3),\quad B(4, -5)`)],
      ex: { k: 'val', v: '10', q: R`Find the distance between $A(-2, 3)$ and $B(4, -5)$.|Calculez la distance entre $A(-2, 3)$ et $B(4, -5)$.|Halla la distancia entre $A(-2, 3)$ y $B(4, -5)$.|$A(-2, 3)$ と $B(4, -5)$ の距離を求めよ。|求 $A(-2, 3)$ 与 $B(4, -5)$ 的距离。`, sol: [R`\Delta x = 6,\ \Delta y = -8`, R`\sqrt{36 + 64} = 10`] } });

  lesson('Points/Midpoint', 'Midpoint|Milieu|Punto medio|中点|中点',
    { s: R`The midpoint is halfway in each direction: average the $x$-coordinates and average the $y$-coordinates. It is also how you find a missing endpoint: $B = 2M - A$.|Le milieu est à mi-chemin dans chaque direction : on fait la moyenne des abscisses et celle des ordonnées. On trouve aussi une extrémité manquante : $B = 2M - A$.|El punto medio está a mitad de camino en cada dirección: media de las $x$ y media de las $y$. También sirve para hallar un extremo que falta: $B = 2M - A$.|中点は各方向の真ん中：$x$ 座標と $y$ 座標をそれぞれ平均。端点を求めるときは $B = 2M - A$。|中点在每个方向上都位于正中：横坐标取平均，纵坐标取平均。也可求缺失的端点：$B = 2M - A$。`,
      a: [Y(R`M = \left(\frac{x_1 + x_2}{2},\ \frac{y_1 + y_2}{2}\right)`), EQ([0, 7], [-2, 6]), SEGL(2, -1, 6, 5, 'b'), PTL(2, -1, 'A', 'b'), PTL(6, 5, 'B', 'b'), PTL(4, 2, 'M')] },
    { s: R`$A(2, -1)$, $B(6, 5)$: $M = \left(\tfrac{8}{2}, \tfrac{4}{2}\right) = (4, 2)$.|$A(2, -1)$, $B(6, 5)$ : $M = (4, 2)$.|$A(2, -1)$, $B(6, 5)$: $M = (4, 2)$.|$M = (4, 2)$。|$M = (4, 2)$。`,
      a: [Y(R`M = \left(\frac{2 + 6}{2},\ \frac{-1 + 5}{2}\right) = (4, 2)`)] },
    { s: TRY_P, a: [F(R`A(-3, 4),\quad B(5, 0)`)],
      ex: { k: 'pt', v: [1, 2], q: R`Find the midpoint of $A(-3, 4)$ and $B(5, 0)$.|Trouvez le milieu de $A(-3, 4)$ et $B(5, 0)$.|Halla el punto medio de $A(-3, 4)$ y $B(5, 0)$.|$A(-3, 4)$ と $B(5, 0)$ の中点を求めよ。|求 $A(-3, 4)$ 与 $B(5, 0)$ 的中点。`, sol: [R`\left(\frac{-3 + 5}{2},\ \frac{4 + 0}{2}\right)`, R`= (1, 2)`] } });

  lesson('Points/Dividing in a ratio m : n', 'Dividing a segment in a ratio|Partage d’un segment dans un rapport|División de un segmento en una razón|線分の内分点|定比分点',
    { s: R`$P$ divides $AB$ so that $AP : PB = m : n$. It is a weighted average where each endpoint is weighted by the share on the other side: $B$ gets weight $m$, $A$ gets $n$. Equivalently $P = A + \tfrac{m}{m + n}(B - A)$.|$P$ partage $AB$ de sorte que $AP : PB = m : n$. C’est une moyenne pondérée où chaque extrémité a le poids de la part opposée : $B$ pèse $m$, $A$ pèse $n$. Autrement dit $P = A + \tfrac{m}{m + n}(B - A)$.|$P$ divide $AB$ de modo que $AP : PB = m : n$. Es una media ponderada en la que cada extremo pesa lo del otro lado: $B$ pesa $m$ y $A$ pesa $n$. Equivalentemente $P = A + \tfrac{m}{m + n}(B - A)$.|$AP : PB = m : n$ となる点 $P$。反対側の比を重みとする加重平均（$B$ に $m$、$A$ に $n$）。$P = A + \tfrac{m}{m + n}(B - A)$ とも書ける。|$P$ 把 $AB$ 分成 $AP : PB = m : n$。这是加权平均，每个端点的权是另一侧的份数：$B$ 权 $m$，$A$ 权 $n$。等价地 $P = A + \tfrac{m}{m + n}(B - A)$。`,
      a: [Y(R`P = \left(\frac{n x_1 + m x_2}{m + n},\ \frac{n y_1 + m y_2}{m + n}\right)`, { s: 22 }), EQ([0, 8], [0, 6]), SEGL(1, 2, 7, 5, 'b'), PTL(1, 2, 'A', 'b'), PTL(7, 5, 'B', 'b'), PTL(3, 3, 'P (1 : 2)')] },
    { s: R`$A(1, 2)$, $B(7, 5)$, $AP : PB = 1 : 2$: $P = \left(\tfrac{2\cdot 1 + 1\cdot 7}{3}, \tfrac{2\cdot 2 + 1\cdot 5}{3}\right) = (3, 3)$ — one third of the way from $A$.|$A(1, 2)$, $B(7, 5)$, $AP : PB = 1 : 2$ : $P = (3, 3)$ — au tiers du chemin depuis $A$.|$A(1, 2)$, $B(7, 5)$, $AP : PB = 1 : 2$: $P = (3, 3)$, a un tercio del camino desde $A$.|$P = (3, 3)$（$A$ から 1/3）。|$P = (3, 3)$（距 $A$ 三分之一）。`,
      a: [F(R`P = \left(\frac{2\cdot 1 + 7}{3},\ \frac{2\cdot 2 + 5}{3}\right)`), Y(R`= (3, 3)`)] },
    { s: TRY_P, a: [F(R`A(0, 0),\ B(10, 5),\ AP : PB = 3 : 2`)],
      ex: { k: 'pt', v: [6, 3], q: R`Find $P$ on $AB$ with $A(0, 0)$, $B(10, 5)$ and $AP : PB = 3 : 2$.|Trouvez $P$ sur $AB$ avec $A(0, 0)$, $B(10, 5)$ et $AP : PB = 3 : 2$.|Halla $P$ en $AB$ con $A(0, 0)$, $B(10, 5)$ y $AP : PB = 3 : 2$.|$A(0, 0)$, $B(10, 5)$、$AP : PB = 3 : 2$ となる $P$ を求めよ。|$A(0, 0)$，$B(10, 5)$，$AP : PB = 3 : 2$，求 $P$。`, sol: [R`P = A + \tfrac35(B - A)`, R`= (6, 3)`] } });

  lesson('Points/Centroid of a triangle', 'Centroid of a triangle|Centre de gravité d’un triangle|Baricentro de un triángulo|三角形の重心|三角形的重心',
    { s: R`The three medians meet at the centroid $G$, which is simply the average of the three vertices. It divides every median in the ratio $2 : 1$ from the vertex — and it is where a cardboard triangle balances.|Les trois médianes se coupent au centre de gravité $G$, qui est simplement la moyenne des trois sommets. Il partage chaque médiane dans le rapport $2 : 1$ depuis le sommet — c’est là qu’un triangle en carton tient en équilibre.|Las tres medianas se cortan en el baricentro $G$, que es simplemente la media de los tres vértices. Divide cada mediana en razón $2 : 1$ desde el vértice, y es donde un triángulo de cartón se equilibra.|3 本の中線は重心 $G$ で交わり、$G$ は 3 頂点の平均。各中線を頂点から $2 : 1$ に分け、厚紙の三角形が釣り合う点。|三条中线交于重心 $G$，它就是三个顶点的平均。它把每条中线从顶点起分成 $2 : 1$——纸板三角形在这里平衡。`,
      a: [Y(R`G = \left(\frac{x_1 + x_2 + x_3}{3},\ \frac{y_1 + y_2 + y_3}{3}\right)`, { s: 22 }), EQ([-1, 7], [-1, 7]), SEGL(0, 0, 6, 0), SEGL(6, 0, 3, 6), SEGL(3, 6, 0, 0), SEGL(0, 0, 4.5, 3, 'g', { dash: true }), SEGL(6, 0, 1.5, 3, 'g', { dash: true }), SEGL(3, 6, 3, 0, 'g', { dash: true }), PTL(3, 2, 'G')] },
    { s: R`Vertices $(0, 0)$, $(6, 0)$, $(3, 6)$: $G = \left(\tfrac{9}{3}, \tfrac{6}{3}\right) = (3, 2)$, one third of the height above the base.|Sommets $(0, 0)$, $(6, 0)$, $(3, 6)$ : $G = (3, 2)$, au tiers de la hauteur.|Vértices $(0, 0)$, $(6, 0)$, $(3, 6)$: $G = (3, 2)$, a un tercio de la altura.|$G = (3, 2)$。|$G = (3, 2)$。`,
      a: [Y(R`G = \left(\frac{0 + 6 + 3}{3},\ \frac{0 + 0 + 6}{3}\right) = (3, 2)`, { s: 22 })] },
    { s: TRY_P, a: [F(R`(1, 1),\ (5, 3),\ (3, 8)`)],
      ex: { k: 'pt', v: [3, 4], q: R`Find the centroid of the triangle with vertices $(1, 1)$, $(5, 3)$, $(3, 8)$.|Trouvez le centre de gravité du triangle de sommets $(1, 1)$, $(5, 3)$, $(3, 8)$.|Halla el baricentro del triángulo de vértices $(1, 1)$, $(5, 3)$, $(3, 8)$.|頂点 $(1, 1)$, $(5, 3)$, $(3, 8)$ の三角形の重心を求めよ。|求顶点为 $(1, 1)$、$(5, 3)$、$(3, 8)$ 的三角形重心。`, sol: [R`\left(\frac{9}{3},\ \frac{12}{3}\right)`, R`= (3, 4)`] } });

  lesson('Points/Triangle area', 'Area of a triangle from coordinates|Aire d’un triangle par coordonnées|Área de un triángulo por coordenadas|座標による三角形の面積|坐标求三角形面积',
    { s: R`The “shoelace” formula gives the area straight from the coordinates, with no heights to find. The sign of the bracket tells the orientation (counter-clockwise positive), so take the absolute value. If it is 0, the points are collinear.|La formule « du lacet » donne l’aire directement à partir des coordonnées, sans chercher de hauteur. Le signe de la parenthèse indique l’orientation (positif dans le sens trigonométrique) : on prend la valeur absolue. S’il vaut 0, les points sont alignés.|La fórmula «del cordón» da el área directamente con las coordenadas, sin buscar alturas. El signo del paréntesis indica la orientación (positivo en sentido antihorario), así que se toma el valor absoluto. Si es 0, los puntos están alineados.|「靴ひも公式」は座標から直接面積を出す（高さ不要）。括弧の符号は向き（反時計回りで正）なので絶対値をとる。0 なら 3 点は一直線上。|“鞋带公式”直接由坐标得面积，不必求高。括号的符号表示方向（逆时针为正），所以取绝对值。为 0 时三点共线。`,
      a: [Y(R`S = \tfrac12\left\lvert x_1(y_2 - y_3) + x_2(y_3 - y_1) + x_3(y_1 - y_2)\right\rvert`, { s: 20 }), EQ([-1, 5], [-1, 4]), SEGL(0, 0, 4, 0, 'y'), SEGL(4, 0, 1, 3, 'y'), SEGL(1, 3, 0, 0, 'y'), PTL(0, 0, ''), PTL(4, 0, ''), PTL(1, 3, '')] },
    { s: R`$(0, 0)$, $(4, 0)$, $(1, 3)$: $\tfrac12\lvert 0 + 4(3 - 0) + 1(0 - 0)\rvert = 6$ — the same as base 4 × height 3 ÷ 2.|$(0, 0)$, $(4, 0)$, $(1, 3)$ : $\tfrac12\lvert 12\rvert = 6$ — comme base 4 × hauteur 3 ÷ 2.|$(0, 0)$, $(4, 0)$, $(1, 3)$: $\tfrac12\lvert 12\rvert = 6$, igual que base 4 × altura 3 ÷ 2.|$S = 6$（底 4 × 高さ 3 ÷ 2 と同じ）。|$S = 6$（底 4 × 高 3 ÷ 2）。`,
      a: [Y(R`S = \tfrac12\lvert 4\cdot 3\rvert = 6`)] },
    { a: [F(R`(1, 1),\ (4, 2),\ (2, 5)`)],
      ex: { k: 'val', v: '5.5', q: R`Find the area of the triangle with vertices $(1, 1)$, $(4, 2)$, $(2, 5)$.|Calculez l’aire du triangle de sommets $(1, 1)$, $(4, 2)$, $(2, 5)$.|Halla el área del triángulo de vértices $(1, 1)$, $(4, 2)$, $(2, 5)$.|頂点 $(1, 1)$, $(4, 2)$, $(2, 5)$ の三角形の面積を求めよ。|求顶点为 $(1, 1)$、$(4, 2)$、$(2, 5)$ 的三角形面积。`, sol: [R`1(2 - 5) + 4(5 - 1) + 2(1 - 2) = 11`, R`S = \frac{11}{2} = 5.5`] } });

  lesson('Points/Distance in space', 'Distance in space|Distance dans l’espace|Distancia en el espacio|空間での距離|空间两点间距离',
    { s: R`In three dimensions apply Pythagoras twice: first across the floor ($\Delta x$, $\Delta y$), then up ($\Delta z$). The result is one more square under the root.|En dimension 3 on applique Pythagore deux fois : d’abord au sol ($\Delta x$, $\Delta y$), puis en hauteur ($\Delta z$). On obtient un carré de plus sous la racine.|En tres dimensiones se aplica Pitágoras dos veces: primero en el suelo ($\Delta x$, $\Delta y$) y luego en altura ($\Delta z$). Sale un cuadrado más bajo la raíz.|3 次元では三平方の定理を 2 回（床で $\Delta x$, $\Delta y$、次に高さ $\Delta z$）。根号の中に 2 乗が 1 つ増える。|三维中用两次勾股定理：先在底面（$\Delta x$、$\Delta y$），再向上（$\Delta z$）。根号下多一个平方。`,
      a: [Y(R`d = \sqrt{\Delta x^2 + \Delta y^2 + \Delta z^2}`), ['3d', { c: [1, 1.5, 1.5], r: 2.6, yaw: -0.8 }], ['seg', [0, 0, 0], [2, 3, 3], { c: 'y', w: 3 }], ['seg', [0, 0, 0], [2, 3, 0], { c: 'b', dash: true }], ['seg', [2, 3, 0], [2, 3, 3], { c: 'b', dash: true }], ['pt3', [0, 0, 0], 'A', { c: 'o' }], ['pt3', [2, 3, 3], 'B', { c: 'o' }]] },
    { s: R`$(1, 2, 3)$ to $(3, 5, 9)$: $\sqrt{4 + 9 + 36} = \sqrt{49} = 7$.|$(1, 2, 3)$ à $(3, 5, 9)$ : $\sqrt{49} = 7$.|$(1, 2, 3)$ a $(3, 5, 9)$: $\sqrt{49} = 7$.|$\sqrt{4 + 9 + 36} = 7$。|$\sqrt{4 + 9 + 36} = 7$。`,
      a: [Y(R`\sqrt{2^2 + 3^2 + 6^2} = 7`)] },
    { a: [F(R`(0, 1, -2),\quad (2, -1, -1)`)],
      ex: { k: 'val', v: '3', q: R`Find the distance between $(0, 1, -2)$ and $(2, -1, -1)$.|Calculez la distance entre $(0, 1, -2)$ et $(2, -1, -1)$.|Halla la distancia entre $(0, 1, -2)$ y $(2, -1, -1)$.|$(0, 1, -2)$ と $(2, -1, -1)$ の距離を求めよ。|求 $(0, 1, -2)$ 与 $(2, -1, -1)$ 的距离。`, sol: [R`\sqrt{4 + 4 + 1}`, R`= 3`] } });

  // =============================== Lines ===============================
  lesson('Lines/Slope', 'Slope of a line|Pente d’une droite|Pendiente de una recta|直線の傾き|直线的斜率',
    { s: R`The slope is “rise over run”: how much $y$ changes when $x$ increases by 1. It equals $\tan\alpha$, where $\alpha$ is the angle with the positive $x$-axis. Vertical lines have no slope.|La pente est « montée sur avancée » : de combien $y$ change quand $x$ augmente de 1. Elle vaut $\tan\alpha$, où $\alpha$ est l’angle avec l’axe des $x$. Les droites verticales n’ont pas de pente.|La pendiente es «subida entre avance»: cuánto cambia $y$ cuando $x$ aumenta 1. Es $\tan\alpha$, siendo $\alpha$ el ángulo con el eje $x$ positivo. Las rectas verticales no tienen pendiente.|傾きは「縦の変化 ÷ 横の変化」：$x$ が 1 増えたときの $y$ の変化。$x$ 軸の正の向きとの角 $\alpha$ について $\tan\alpha$。垂直な直線には傾きがない。|斜率是“升高除以前进”：$x$ 增加 1 时 $y$ 的变化。它等于 $\tan\alpha$，$\alpha$ 是与 $x$ 轴正向的夹角。竖直线没有斜率。`,
      a: [Y(R`m = \frac{y_2 - y_1}{x_2 - x_1} = \tan\alpha`), EQ([-1, 6], [-1, 8]), P('2x-1'), SEGL(1, 1, 4, 1, 'b', { dash: true }), SEGL(4, 1, 4, 7, 'b', { dash: true }), PTL(1, 1, ''), PTL(4, 7, '')] },
    { s: R`Through $(1, 1)$ and $(4, 7)$: $m = \tfrac{6}{3} = 2$, so the angle is $\alpha = \arctan 2 \approx 63.4°$.|Par $(1, 1)$ et $(4, 7)$ : $m = 2$, angle $\alpha = \arctan 2 \approx 63{,}4°$.|Por $(1, 1)$ y $(4, 7)$: $m = 2$, ángulo $\alpha = \arctan 2 \approx 63{,}4°$.|$m = 2$、$\alpha \approx 63.4°$。|$m = 2$，$\alpha \approx 63.4°$。`,
      a: [F(R`m = \frac{7 - 1}{4 - 1} = 2`), Y(R`\alpha = \arctan 2 \approx 63.4^\circ`)] },
    { a: [F(R`(-2, 5),\quad (3, -5)`)],
      ex: { k: 'val', v: '-2', q: R`Find the slope of the line through $(-2, 5)$ and $(3, -5)$.|Trouvez la pente de la droite par $(-2, 5)$ et $(3, -5)$.|Halla la pendiente de la recta por $(-2, 5)$ y $(3, -5)$.|$(-2, 5)$, $(3, -5)$ を通る直線の傾きを求めよ。|求过 $(-2, 5)$ 与 $(3, -5)$ 的直线斜率。`, sol: [R`m = \frac{-5 - 5}{3 + 2}`, R`= -2`] } });

  lesson('Lines/Forms of a line', 'Equations of a line|Équations d’une droite|Ecuaciones de una recta|直線の方程式|直线方程',
    { s: R`Slope–intercept $y = mx + b$ is best for drawing; point–slope $y - y_1 = m(x - x_1)$ is best when you know a point and the slope; the general form $Ax + By + C = 0$ also covers vertical lines and is what the distance formula uses.|La forme réduite $y = mx + b$ est idéale pour tracer ; la forme point–pente $y - y_1 = m(x - x_1)$ quand on connaît un point et la pente ; la forme générale $Ax + By + C = 0$ couvre aussi les droites verticales et sert à la formule de distance.|La forma explícita $y = mx + b$ es ideal para dibujar; la punto–pendiente $y - y_1 = m(x - x_1)$ cuando conoces un punto y la pendiente; la general $Ax + By + C = 0$ incluye las verticales y es la que usa la fórmula de distancia.|傾き切片形 $y = mx + b$ は描くのに、点傾き形 $y - y_1 = m(x - x_1)$ は点と傾きがわかるときに、一般形 $Ax + By + C = 0$ は垂直線も表せて距離公式で使う。|斜截式 $y = mx + b$ 便于作图；点斜式 $y - y_1 = m(x - x_1)$ 适合已知一点和斜率；一般式 $Ax + By + C = 0$ 也包括竖直线，距离公式用它。`,
      a: [Y(R`y = mx + b,\quad y - y_1 = m(x - x_1),\quad Ax + By + C = 0`, { s: 20 }), EQ([-1, 6], [-1, 6]), P('-x+5'), PTL(2, 3, '(2, 3)')] },
    { s: R`Through $(2, 3)$ with slope $-1$: $y - 3 = -(x - 2)$, i.e. $y = -x + 5$, or $x + y - 5 = 0$.|Par $(2, 3)$ de pente $-1$ : $y - 3 = -(x - 2)$, soit $y = -x + 5$, ou $x + y - 5 = 0$.|Por $(2, 3)$ con pendiente $-1$: $y - 3 = -(x - 2)$, es decir $y = -x + 5$, o $x + y - 5 = 0$.|$y = -x + 5$、$x + y - 5 = 0$。|$y = -x + 5$，即 $x + y - 5 = 0$。`,
      a: [F(R`y - 3 = -(x - 2)`), Y(R`y = -x + 5 \iff x + y - 5 = 0`)] },
    { s: TRY_E, a: [F(R`(1, -2),\quad m = 3`)],
      ex: { k: 'expr', f: '3x-5', q: R`Find the line through $(1, -2)$ with slope 3.|Trouvez la droite passant par $(1, -2)$ de pente 3.|Halla la recta que pasa por $(1, -2)$ con pendiente 3.|$(1, -2)$ を通り傾き 3 の直線を求めよ。|求过 $(1, -2)$ 且斜率为 3 的直线。`, sol: [R`y + 2 = 3(x - 1)`, R`y = 3x - 5`] } });

  lesson('Lines/Intercept form', 'Intercept form|Équation segmentaire|Forma segmentaria|切片形|截距式',
    { s: R`If a line cuts the axes at $(a, 0)$ and $(0, b)$, its equation is $\tfrac xa + \tfrac yb = 1$: put $y = 0$ and you get $x = a$. To read the intercepts from $Ax + By = C$, divide by $C$.|Si une droite coupe les axes en $(a, 0)$ et $(0, b)$, son équation est $\tfrac xa + \tfrac yb = 1$ : avec $y = 0$ on trouve $x = a$. Pour lire les points d’intersection de $Ax + By = C$, on divise par $C$.|Si una recta corta los ejes en $(a, 0)$ y $(0, b)$, su ecuación es $\tfrac xa + \tfrac yb = 1$: con $y = 0$ sale $x = a$. Para leer los cortes de $Ax + By = C$, divide entre $C$.|軸と $(a, 0)$, $(0, b)$ で交わる直線は $\tfrac xa + \tfrac yb = 1$（$y = 0$ で $x = a$）。$Ax + By = C$ は $C$ で割れば切片が読める。|与坐标轴交于 $(a, 0)$、$(0, b)$ 的直线为 $\tfrac xa + \tfrac yb = 1$（令 $y = 0$ 得 $x = a$）。从 $Ax + By = C$ 读截距，就除以 $C$。`,
      a: [Y(R`\frac xa + \frac yb = 1`, { s: 30 }), EQ([-1, 6], [-1, 4]), P('2-x/2'), PTL(4, 0, '(a, 0)'), PTL(0, 2, '(0, b)')] },
    { s: R`$\tfrac x4 + \tfrac y2 = 1$ meets the axes at $(4, 0)$ and $(0, 2)$; multiplying by 4 gives $x + 2y = 4$.|$\tfrac x4 + \tfrac y2 = 1$ coupe les axes en $(4, 0)$ et $(0, 2)$ ; en multipliant par 4 : $x + 2y = 4$.|$\tfrac x4 + \tfrac y2 = 1$ corta los ejes en $(4, 0)$ y $(0, 2)$; multiplicando por 4: $x + 2y = 4$.|$(4, 0)$, $(0, 2)$ を通り $x + 2y = 4$。|过 $(4, 0)$、$(0, 2)$，即 $x + 2y = 4$。`,
      a: [Y(R`\frac x4 + \frac y2 = 1 \iff x + 2y = 4`)] },
    { a: [F(R`2x + 3y = 12`), EQ([-1, 7], [-1, 5]), P('4-2x/3')],
      ex: { k: 'val', v: '12', q: R`Find the area of the triangle formed by the line $2x + 3y = 12$ and the two axes.|Calculez l’aire du triangle formé par la droite $2x + 3y = 12$ et les deux axes.|Halla el área del triángulo que forma la recta $2x + 3y = 12$ con los ejes.|直線 $2x + 3y = 12$ と 2 軸で囲まれた三角形の面積を求めよ。|求直线 $2x + 3y = 12$ 与两坐标轴围成的三角形面积。`, sol: [R`\frac x6 + \frac y4 = 1:\ a = 6,\ b = 4`, R`S = \frac{6\cdot 4}{2} = 12`] } });

  lesson('Lines/Parallel and perpendicular', 'Parallel and perpendicular lines|Droites parallèles et perpendiculaires|Rectas paralelas y perpendiculares|平行と垂直|平行与垂直',
    { s: R`Parallel lines rise at the same rate: equal slopes. Perpendicular lines have slopes that multiply to $-1$: flip the slope and change its sign ($2 \to -\tfrac12$).|Des droites parallèles montent au même rythme : pentes égales. Des droites perpendiculaires ont des pentes dont le produit vaut $-1$ : on inverse la pente et on change son signe ($2 \to -\tfrac12$).|Las paralelas suben al mismo ritmo: pendientes iguales. Las perpendiculares tienen pendientes cuyo producto es $-1$: invierte la pendiente y cambia el signo ($2 \to -\tfrac12$).|平行な直線は傾きが等しい。垂直な直線は傾きの積が $-1$（逆数にして符号を変える：$2 \to -\tfrac12$）。|平行线斜率相等。垂直线斜率之积为 $-1$：取倒数再变号（$2 \to -\tfrac12$）。`,
      a: [Y(R`\parallel:\ m_1 = m_2,\qquad \perp:\ m_1 m_2 = -1`, { s: 24 }), EQ([-2, 5], [-2, 5]), P('2x+1', 'b'), P('2x-3', 'b', { dash: true }), P('-x/2+2')] },
    { s: R`Perpendicular to $y = 2x + 1$ through $(2, 1)$: slope $-\tfrac12$, so $y - 1 = -\tfrac12(x - 2)$, $y = -\tfrac x2 + 2$ (yellow).|Perpendiculaire à $y = 2x + 1$ par $(2, 1)$ : pente $-\tfrac12$, d’où $y = -\tfrac x2 + 2$.|Perpendicular a $y = 2x + 1$ por $(2, 1)$: pendiente $-\tfrac12$, así que $y = -\tfrac x2 + 2$.|傾き $-\tfrac12$ で $y = -\tfrac x2 + 2$。|斜率 $-\tfrac12$，$y = -\tfrac x2 + 2$。`,
      a: [F(R`m = -\tfrac12`), Y(R`y = -\tfrac x2 + 2`), EQ([-2, 5], [-2, 5]), P('2x+1', 'b'), P('-x/2+2'), PTL(2, 1, '(2, 1)')] },
    { s: TRY_E, a: [F(R`y = 3x - 1,\quad (1, 4)`)],
      ex: { k: 'expr', f: '3x+1', q: R`Find the line parallel to $y = 3x - 1$ through $(1, 4)$.|Trouvez la droite parallèle à $y = 3x - 1$ passant par $(1, 4)$.|Halla la recta paralela a $y = 3x - 1$ que pasa por $(1, 4)$.|$y = 3x - 1$ に平行で $(1, 4)$ を通る直線を求めよ。|求过 $(1, 4)$ 且平行于 $y = 3x - 1$ 的直线。`, sol: [R`m = 3:\ y - 4 = 3(x - 1)`, R`y = 3x + 1`] } });

  lesson('Lines/Angle between two lines', 'Angle between two lines|Angle de deux droites|Ángulo entre dos rectas|2 直線のなす角|两直线的夹角',
    { s: R`Each slope is the tangent of an inclination angle; the angle between the lines is the difference of those angles, and the tangent subtraction formula gives this expression. The absolute value picks the acute angle. If $1 + m_1 m_2 = 0$ the lines are perpendicular.|Chaque pente est la tangente d’un angle d’inclinaison ; l’angle des droites est la différence de ces angles, et la formule de $\tan(a - b)$ donne cette expression. La valeur absolue donne l’angle aigu. Si $1 + m_1 m_2 = 0$, les droites sont perpendiculaires.|Cada pendiente es la tangente de un ángulo de inclinación; el ángulo entre las rectas es la diferencia de esos ángulos, y la fórmula de $\tan(a - b)$ da esta expresión. El valor absoluto escoge el ángulo agudo. Si $1 + m_1 m_2 = 0$ son perpendiculares.|傾きは傾斜角の正接。2 直線のなす角は傾斜角の差で、$\tan(a - b)$ の公式からこの式。絶対値で鋭角を選ぶ。$1 + m_1 m_2 = 0$ なら垂直。|斜率是倾斜角的正切；夹角是倾斜角之差，由 $\tan(a - b)$ 公式得此式。绝对值取锐角。若 $1 + m_1 m_2 = 0$ 则垂直。`,
      a: [Y(R`\tan\theta = \left\lvert\frac{m_2 - m_1}{1 + m_1 m_2}\right\rvert`), EQ([-1, 4], [-1, 6]), P('x', 'b'), P('3x')] },
    { s: R`$y = x$ and $y = 3x$: $\tan\theta = \tfrac{3 - 1}{1 + 3} = \tfrac12$, so $\theta \approx 26.6°$.|$y = x$ et $y = 3x$ : $\tan\theta = \tfrac12$, donc $\theta \approx 26{,}6°$.|$y = x$ e $y = 3x$: $\tan\theta = \tfrac12$, así que $\theta \approx 26{,}6°$.|$\tan\theta = \tfrac12$、$\theta \approx 26.6°$。|$\tan\theta = \tfrac12$，$\theta \approx 26.6°$。`,
      a: [F(R`\tan\theta = \frac{3 - 1}{1 + 3} = \frac12`), Y(R`\theta \approx 26.6^\circ`)] },
    { a: [F(R`y = 2x,\quad y = -3x`)],
      ex: { k: 'val', v: '45', q: R`Find the acute angle, in degrees, between $y = 2x$ and $y = -3x$.|Trouvez l’angle aigu, en degrés, entre $y = 2x$ et $y = -3x$.|Halla el ángulo agudo, en grados, entre $y = 2x$ e $y = -3x$.|$y = 2x$ と $y = -3x$ のなす鋭角（度）を求めよ。|求 $y = 2x$ 与 $y = -3x$ 的锐角夹角（度）。`, sol: [R`\tan\theta = \left\lvert\frac{-3 - 2}{1 - 6}\right\rvert = 1`, R`\theta = 45^\circ`] } });

  lesson('Lines/Point to line', 'Distance from a point to a line|Distance d’un point à une droite|Distancia de un punto a una recta|点と直線の距離|点到直线的距离',
    { s: R`The shortest way from a point to a line is along the perpendicular. The formula plugs the point into the line’s general equation — that gives 0 only for points on the line — and divides by $\sqrt{A^2 + B^2}$, the length of the normal vector.|Le plus court chemin d’un point à une droite suit la perpendiculaire. La formule remplace le point dans l’équation générale — ce qui ne donne 0 que pour les points de la droite — et divise par $\sqrt{A^2 + B^2}$, la norme du vecteur normal.|El camino más corto de un punto a una recta es la perpendicular. La fórmula sustituye el punto en la ecuación general, que solo da 0 en los puntos de la recta, y divide entre $\sqrt{A^2 + B^2}$, la longitud del vector normal.|点から直線への最短経路は垂線。一般形に点を代入（直線上なら 0）して法線ベクトルの長さ $\sqrt{A^2 + B^2}$ で割る。|点到直线的最短路径是垂线。公式把点代入一般式（直线上的点才得 0），再除以法向量长度 $\sqrt{A^2 + B^2}$。`,
      a: [Y(R`d = \frac{\lvert Ax_0 + By_0 + C\rvert}{\sqrt{A^2 + B^2}}`), EQ([-2, 4], [-2, 4]), P('(1-3x)/4'), PTL(1, 2, '(1, 2)'), SEGL(1, 2, -0.2, 0.4, 'p', { dash: true })] },
    { s: R`$(1, 2)$ to $3x + 4y - 1 = 0$: $\tfrac{\lvert 3 + 8 - 1\rvert}{5} = \tfrac{10}{5} = 2$.|$(1, 2)$ à $3x + 4y - 1 = 0$ : $\tfrac{10}{5} = 2$.|$(1, 2)$ a $3x + 4y - 1 = 0$: $\tfrac{10}{5} = 2$.|$d = 2$。|$d = 2$。`,
      a: [Y(R`d = \frac{\lvert 3\cdot 1 + 4\cdot 2 - 1\rvert}{\sqrt{9 + 16}} = 2`)] },
    { a: [F(R`(3, 1),\quad 5x - 12y + 10 = 0`)],
      ex: { k: 'val', v: '1', q: R`Find the distance from $(3, 1)$ to the line $5x - 12y + 10 = 0$.|Calculez la distance de $(3, 1)$ à la droite $5x - 12y + 10 = 0$.|Halla la distancia de $(3, 1)$ a la recta $5x - 12y + 10 = 0$.|$(3, 1)$ と直線 $5x - 12y + 10 = 0$ の距離を求めよ。|求 $(3, 1)$ 到直线 $5x - 12y + 10 = 0$ 的距离。`, sol: [R`\lvert 15 - 12 + 10\rvert = 13`, R`d = \frac{13}{13} = 1`] } });

  lesson('Lines/Parallel lines', 'Distance between parallel lines|Distance entre deux droites parallèles|Distancia entre rectas paralelas|平行な 2 直線の距離|两平行线间距离',
    { s: R`Write both lines with the same $A$ and $B$ (multiply one if needed). Then the distance is the gap between the constants divided by the length of the normal vector.|On écrit les deux droites avec les mêmes $A$ et $B$ (en multipliant l’une si besoin). La distance est alors l’écart des constantes divisé par la norme du vecteur normal.|Escribe las dos rectas con los mismos $A$ y $B$ (multiplica una si hace falta). La distancia es la diferencia de las constantes entre la longitud del vector normal.|両方の直線を同じ $A$, $B$ で書く（必要なら定数倍）。距離は定数項の差 ÷ 法線ベクトルの長さ。|把两直线写成相同的 $A$、$B$（必要时乘一个数），距离就是常数项之差除以法向量长度。`,
      a: [Y(R`d = \frac{\lvert C_1 - C_2\rvert}{\sqrt{A^2 + B^2}}`), EQ([-4, 4], [-4, 4]), P('(2-3x)/4'), P('(-8-3x)/4', 'b')] },
    { s: R`$3x + 4y - 2 = 0$ and $3x + 4y + 8 = 0$: $d = \tfrac{\lvert -2 - 8\rvert}{5} = 2$.|$3x + 4y - 2 = 0$ et $3x + 4y + 8 = 0$ : $d = \tfrac{10}{5} = 2$.|$3x + 4y - 2 = 0$ y $3x + 4y + 8 = 0$: $d = \tfrac{10}{5} = 2$.|$d = 2$。|$d = 2$。`,
      a: [Y(R`d = \frac{\lvert -2 - 8\rvert}{5} = 2`)] },
    { a: [F(R`2x - y + 3 = 0,\quad 2x - y - 7 = 0`)],
      ex: { k: 'val', v: '2sqrt(5)', q: R`Find the distance between $2x - y + 3 = 0$ and $2x - y - 7 = 0$.|Calculez la distance entre $2x - y + 3 = 0$ et $2x - y - 7 = 0$.|Halla la distancia entre $2x - y + 3 = 0$ y $2x - y - 7 = 0$.|$2x - y + 3 = 0$ と $2x - y - 7 = 0$ の距離を求めよ。|求 $2x - y + 3 = 0$ 与 $2x - y - 7 = 0$ 的距离。`, sol: [R`\frac{\lvert 3 + 7\rvert}{\sqrt{4 + 1}} = \frac{10}{\sqrt5}`, R`= 2\sqrt5 \approx 4.47`] } });

  // =============================== Circles ===============================
  lesson('Circles/Centre and radius', 'Equation of a circle|Équation d’un cercle|Ecuación de una circunferencia|円の方程式|圆的方程',
    { s: R`A circle is every point at distance $r$ from the centre $(a, b)$. Write that distance with the distance formula and square it: that is the equation. Watch the signs: $(y + 1)^2$ means $b = -1$.|Un cercle est l’ensemble des points à distance $r$ du centre $(a, b)$. On écrit cette distance et on l’élève au carré : c’est l’équation. Attention aux signes : $(y + 1)^2$ signifie $b = -1$.|Una circunferencia son los puntos a distancia $r$ del centro $(a, b)$. Escribe esa distancia y elévala al cuadrado: esa es la ecuación. Ojo con los signos: $(y + 1)^2$ significa $b = -1$.|円は中心 $(a, b)$ から距離 $r$ の点全体。距離の式を 2 乗したものが方程式。符号に注意：$(y + 1)^2$ は $b = -1$。|圆是到圆心 $(a, b)$ 距离为 $r$ 的点集。写出距离并平方即得方程。注意符号：$(y + 1)^2$ 表示 $b = -1$。`,
      a: [Y(R`(x - a)^2 + (y - b)^2 = r^2`), EQ([-2, 6], [-5, 3]), IP('(x-2)^2+(y+1)^2=9'), PTL(2, -1, '(2, −1)'), SEGL(2, -1, 5, -1, 'b')] },
    { s: R`$(x - 2)^2 + (y + 1)^2 = 9$: centre $(2, -1)$, radius $\sqrt 9 = 3$.|$(x - 2)^2 + (y + 1)^2 = 9$ : centre $(2, -1)$, rayon 3.|$(x - 2)^2 + (y + 1)^2 = 9$: centro $(2, -1)$, radio 3.|中心 $(2, -1)$、半径 3。|圆心 $(2, -1)$，半径 3。`,
      a: [Y(R`C(2, -1),\quad r = 3`)] },
    { a: [F(R`C(1, -3),\quad P(4, 1)\ \text{on the circle}`)],
      ex: { k: 'val', v: '5', q: R`A circle has centre $(1, -3)$ and passes through $(4, 1)$. Find its radius.|Un cercle a pour centre $(1, -3)$ et passe par $(4, 1)$. Trouvez son rayon.|Una circunferencia tiene centro $(1, -3)$ y pasa por $(4, 1)$. Halla su radio.|中心 $(1, -3)$ で $(4, 1)$ を通る円の半径を求めよ。|圆心 $(1, -3)$ 且过 $(4, 1)$ 的圆的半径是多少？`, sol: [R`r = \sqrt{3^2 + 4^2}`, R`= 5`] } });

  lesson('Circles/General form', 'General form of a circle|Équation développée d’un cercle|Forma general de la circunferencia|円の一般形|圆的一般方程',
    { s: R`Expanding the squares gives $x^2 + y^2 + Dx + Ey + F = 0$. To go back, complete the square in $x$ and in $y$: the centre is $\left(-\tfrac D2, -\tfrac E2\right)$ and $r^2 = \tfrac{D^2 + E^2}{4} - F$ — if that is negative there is no circle.|En développant on obtient $x^2 + y^2 + Dx + Ey + F = 0$. Pour revenir, on complète les carrés en $x$ et en $y$ : le centre est $\left(-\tfrac D2, -\tfrac E2\right)$ et $r^2 = \tfrac{D^2 + E^2}{4} - F$ — s’il est négatif, il n’y a pas de cercle.|Al desarrollar sale $x^2 + y^2 + Dx + Ey + F = 0$. Para volver, completa cuadrados en $x$ y en $y$: el centro es $\left(-\tfrac D2, -\tfrac E2\right)$ y $r^2 = \tfrac{D^2 + E^2}{4} - F$; si es negativo no hay circunferencia.|展開すると $x^2 + y^2 + Dx + Ey + F = 0$。戻すには $x$, $y$ それぞれ平方完成：中心 $\left(-\tfrac D2, -\tfrac E2\right)$、$r^2 = \tfrac{D^2 + E^2}{4} - F$（負なら円でない）。|展开得 $x^2 + y^2 + Dx + Ey + F = 0$。反过来对 $x$、$y$ 分别配方：圆心 $\left(-\tfrac D2, -\tfrac E2\right)$，$r^2 = \tfrac{D^2 + E^2}{4} - F$——为负则不是圆。`,
      a: [Y(R`x^2 + y^2 + Dx + Ey + F = 0`), F(R`C\left(-\tfrac D2, -\tfrac E2\right),\quad r^2 = \tfrac{D^2 + E^2}{4} - F`, { s: 22 })] },
    { s: R`$x^2 + y^2 - 6x + 4y - 3 = 0$: $(x - 3)^2 - 9 + (y + 2)^2 - 4 - 3 = 0$, so $(x - 3)^2 + (y + 2)^2 = 16$: centre $(3, -2)$, radius 4.|$x^2 + y^2 - 6x + 4y - 3 = 0$ : $(x - 3)^2 + (y + 2)^2 = 16$ : centre $(3, -2)$, rayon 4.|$x^2 + y^2 - 6x + 4y - 3 = 0$: $(x - 3)^2 + (y + 2)^2 = 16$: centro $(3, -2)$, radio 4.|中心 $(3, -2)$、半径 4。|圆心 $(3, -2)$，半径 4。`,
      a: [F(R`(x - 3)^2 - 9 + (y + 2)^2 - 4 - 3 = 0`), Y(R`(x - 3)^2 + (y + 2)^2 = 16`), EQ([-2, 8], [-7, 3]), IP('x^2+y^2-6x+4y-3=0'), PTL(3, -2, '(3, −2)')] },
    { s: TRY_P, a: [F(R`x^2 + y^2 + 4x - 10y + 20 = 0`)],
      ex: { k: 'pt', v: [-2, 5], q: R`Find the centre of the circle $x^2 + y^2 + 4x - 10y + 20 = 0$.|Trouvez le centre du cercle $x^2 + y^2 + 4x - 10y + 20 = 0$.|Halla el centro de la circunferencia $x^2 + y^2 + 4x - 10y + 20 = 0$.|円 $x^2 + y^2 + 4x - 10y + 20 = 0$ の中心を求めよ。|求圆 $x^2 + y^2 + 4x - 10y + 20 = 0$ 的圆心。`, sol: [R`(x + 2)^2 + (y - 5)^2 = 9`, R`C(-2, 5),\ r = 3`] } });

  lesson('Circles/Tangent at a point', 'Tangent at a point of a circle|Tangente en un point d’un cercle|Tangente en un punto de la circunferencia|円の接線|圆的切线',
    { s: R`The tangent is perpendicular to the radius at the point of contact. The formula comes from “doubling”: replace one factor of each square by the point’s coordinates. For a circle centred at the origin it is simply $x_0x + y_0y = r^2$.|La tangente est perpendiculaire au rayon au point de contact. La formule vient du « dédoublement » : on remplace un facteur de chaque carré par les coordonnées du point. Pour un cercle centré à l’origine : $x_0x + y_0y = r^2$.|La tangente es perpendicular al radio en el punto de contacto. La fórmula sale de «desdoblar»: cambia un factor de cada cuadrado por las coordenadas del punto. Para una circunferencia centrada en el origen: $x_0x + y_0y = r^2$.|接線は接点で半径に垂直。各 2 乗の片方を接点の座標に置き換える（原点中心なら $x_0x + y_0y = r^2$）。|切线在切点处垂直于半径。公式来自“分写”：把每个平方的一个因子换成切点坐标。圆心在原点时就是 $x_0x + y_0y = r^2$。`,
      a: [Y(R`(x_0 - a)(x - a) + (y_0 - b)(y - b) = r^2`, { s: 22 }), EQ([-7, 8], [-7, 8]), IP('x^2+y^2=25'), P('(25-3x)/4'), SEGL(0, 0, 3, 4, 'b'), PTL(3, 4, '(3, 4)')] },
    { s: R`$x^2 + y^2 = 25$ at $(3, 4)$: $3x + 4y = 25$, i.e. $y = \tfrac{25 - 3x}{4}$. Its slope $-\tfrac34$ is perpendicular to the radius slope $\tfrac43$.|$x^2 + y^2 = 25$ en $(3, 4)$ : $3x + 4y = 25$. Pente $-\tfrac34$, perpendiculaire au rayon de pente $\tfrac43$.|$x^2 + y^2 = 25$ en $(3, 4)$: $3x + 4y = 25$. Pendiente $-\tfrac34$, perpendicular al radio de pendiente $\tfrac43$.|$3x + 4y = 25$。|$3x + 4y = 25$。`,
      a: [Y(R`3x + 4y = 25`), F(R`-\tfrac34\cdot\tfrac43 = -1\ \checkmark`)] },
    { s: TRY_E, a: [F(R`(x - 1)^2 + (y - 2)^2 = 10,\quad P(2, 5)`)],
      ex: { k: 'expr', f: '(17-x)/3', q: R`Find the tangent to $(x - 1)^2 + (y - 2)^2 = 10$ at $(2, 5)$.|Trouvez la tangente à $(x - 1)^2 + (y - 2)^2 = 10$ en $(2, 5)$.|Halla la tangente a $(x - 1)^2 + (y - 2)^2 = 10$ en $(2, 5)$.|$(x - 1)^2 + (y - 2)^2 = 10$ の $(2, 5)$ での接線を求めよ。|求 $(x - 1)^2 + (y - 2)^2 = 10$ 在 $(2, 5)$ 处的切线。`, sol: [R`1\cdot(x - 1) + 3(y - 2) = 10`, R`x + 3y = 17 \Rightarrow y = \frac{17 - x}{3}`] } });

  lesson('Circles/Line and circle', 'A line and a circle|Position d’une droite et d’un cercle|Posición de recta y circunferencia|直線と円の位置関係|直线与圆的位置关系',
    { s: R`Compare the distance $d$ from the centre to the line with the radius: closer than $r$ — the line cuts the circle twice; exactly $r$ — it touches (tangent); farther — it misses. This avoids solving the system.|On compare la distance $d$ du centre à la droite au rayon : plus petite que $r$ — la droite coupe le cercle en deux points ; égale — elle est tangente ; plus grande — elle ne le rencontre pas. Inutile de résoudre le système.|Compara la distancia $d$ del centro a la recta con el radio: menor que $r$, la recta corta en dos puntos; igual, es tangente; mayor, no lo toca. Así no hay que resolver el sistema.|中心と直線の距離 $d$ と半径を比べる：$d < r$ で 2 点、$d = r$ で接する、$d > r$ で交わらない。連立方程式を解かずに済む。|比较圆心到直线的距离 $d$ 与半径：小于 $r$——交于两点；等于——相切；大于——相离。无需解方程组。`,
      a: [Y(R`d < r:\ 2,\qquad d = r:\ 1,\qquad d > r:\ 0`, { s: 24 }), EQ([-4, 4], [-4, 4]), IP('x^2+y^2=4'), P('x+1', 'b'), P('2.8284-x', 'g'), P('x+4', 'p')] },
    { s: R`$y = x + 1$ and $x^2 + y^2 = 4$: $d = \tfrac{\lvert 1\rvert}{\sqrt2} \approx 0.71 < 2$, so 2 intersection points (blue line).|$y = x + 1$ et $x^2 + y^2 = 4$ : $d = \tfrac{1}{\sqrt2} \approx 0{,}71 < 2$ : 2 points (droite bleue).|$y = x + 1$ y $x^2 + y^2 = 4$: $d = \tfrac{1}{\sqrt2} \approx 0{,}71 < 2$: 2 puntos (recta azul).|$d \approx 0.71 < 2$ で 2 点。|$d \approx 0.71 < 2$，两个交点。`,
      a: [F(R`x - y + 1 = 0:\ d = \frac{1}{\sqrt2}`), Y(R`0.71 < 2 \Rightarrow 2\ \text{points}`)] },
    { a: [F(R`3x + 4y = 20,\quad x^2 + y^2 = 16`)],
      ex: { k: 'val', v: '1', q: R`How many points do the line $3x + 4y = 20$ and the circle $x^2 + y^2 = 16$ have in common?|Combien de points communs ont la droite $3x + 4y = 20$ et le cercle $x^2 + y^2 = 16$ ?|¿Cuántos puntos comunes tienen la recta $3x + 4y = 20$ y la circunferencia $x^2 + y^2 = 16$?|直線 $3x + 4y = 20$ と円 $x^2 + y^2 = 16$ の共有点はいくつか。|直线 $3x + 4y = 20$ 与圆 $x^2 + y^2 = 16$ 有几个公共点？`, sol: [R`d = \frac{\lvert -20\rvert}{5} = 4`, R`d = r\ \Rightarrow\ 1\ \text{(tangent)}`] } });

  // =============================== Ellipse ===============================
  const ELL = (a, b, c = 'y') => IP(`x^2/${a * a}+y^2/${b * b}=1`, c);
  lesson('Ellipse/Equation', 'Equation of an ellipse|Équation d’une ellipse|Ecuación de la elipse|楕円の方程式|椭圆方程',
    { s: R`A circle stretched in one direction. It crosses the $x$-axis at $\pm a$ and the $y$-axis at $\pm b$; with $a > b$ the long (major) axis is horizontal and has length $2a$.|Un cercle étiré dans une direction. Elle coupe l’axe des $x$ en $\pm a$ et l’axe des $y$ en $\pm b$ ; avec $a > b$ le grand axe est horizontal, de longueur $2a$.|Una circunferencia estirada en una dirección. Corta el eje $x$ en $\pm a$ y el eje $y$ en $\pm b$; con $a > b$ el eje mayor es horizontal y mide $2a$.|一方向に引き伸ばした円。$x$ 軸と $\pm a$、$y$ 軸と $\pm b$ で交わる。$a > b$ なら長軸は横で長さ $2a$。|圆沿一个方向拉伸。与 $x$ 轴交于 $\pm a$，与 $y$ 轴交于 $\pm b$；$a > b$ 时长轴水平，长 $2a$。`,
      a: [Y(R`\frac{x^2}{a^2} + \frac{y^2}{b^2} = 1\quad (a > b > 0)`), EQ([-6, 6], [-4, 4]), ELL(5, 3), PTL(5, 0, 'a'), PTL(0, 3, 'b')] },
    { s: R`$\tfrac{x^2}{25} + \tfrac{y^2}{9} = 1$: $a = 5$, $b = 3$. Vertices $(\pm 5, 0)$ and $(0, \pm 3)$; the major axis has length 10.|$\tfrac{x^2}{25} + \tfrac{y^2}{9} = 1$ : $a = 5$, $b = 3$ ; grand axe de longueur 10.|$\tfrac{x^2}{25} + \tfrac{y^2}{9} = 1$: $a = 5$, $b = 3$; eje mayor de longitud 10.|$a = 5$, $b = 3$、長軸 10。|$a = 5$，$b = 3$，长轴 10。`,
      a: [Y(R`a = 5,\ b = 3:\ (\pm 5, 0),\ (0, \pm 3)`)] },
    { a: [F(R`\frac{x^2}{36} + \frac{y^2}{20} = 1`)],
      ex: { k: 'val', v: '12', q: R`Find the length of the major axis of $\tfrac{x^2}{36} + \tfrac{y^2}{20} = 1$.|Trouvez la longueur du grand axe de $\tfrac{x^2}{36} + \tfrac{y^2}{20} = 1$.|Halla la longitud del eje mayor de $\tfrac{x^2}{36} + \tfrac{y^2}{20} = 1$.|$\tfrac{x^2}{36} + \tfrac{y^2}{20} = 1$ の長軸の長さを求めよ。|求 $\tfrac{x^2}{36} + \tfrac{y^2}{20} = 1$ 的长轴长。`, sol: [R`a = 6`, R`2a = 12`] } });

  lesson('Ellipse/Foci', 'Foci of an ellipse|Foyers d’une ellipse|Focos de la elipse|楕円の焦点|椭圆的焦点',
    { s: R`The two foci lie on the major axis at $(\pm c, 0)$, with $c^2 = a^2 - b^2$. Picture the right triangle from the centre to a focus and up to the end of the minor axis: its hypotenuse is $a$.|Les deux foyers sont sur le grand axe en $(\pm c, 0)$, avec $c^2 = a^2 - b^2$. Imaginez le triangle rectangle du centre à un foyer puis au sommet du petit axe : son hypoténuse vaut $a$.|Los dos focos están en el eje mayor en $(\pm c, 0)$, con $c^2 = a^2 - b^2$. Imagina el triángulo rectángulo del centro a un foco y al extremo del eje menor: su hipotenusa es $a$.|2 つの焦点は長軸上の $(\pm c, 0)$、$c^2 = a^2 - b^2$。中心→焦点→短軸の端の直角三角形の斜辺が $a$。|两焦点在长轴上 $(\pm c, 0)$，$c^2 = a^2 - b^2$。从中心到焦点再到短轴端点的直角三角形，斜边为 $a$。`,
      a: [Y(R`F_{1,2} = (\pm c, 0),\qquad c^2 = a^2 - b^2`), EQ([-6, 6], [-4, 4]), ELL(5, 3), PTL(4, 0, 'F₂'), PTL(-4, 0, 'F₁'), SEGL(0, 0, 4, 0, 'b'), SEGL(4, 0, 0, 3, 'p'), SEGL(0, 0, 0, 3, 'b')] },
    { s: R`$a = 5$, $b = 3$: $c^2 = 25 - 9 = 16$, $c = 4$, foci $(\pm 4, 0)$. The pink segment from a focus to $(0, 3)$ has length $a = 5$.|$a = 5$, $b = 3$ : $c = 4$, foyers $(\pm 4, 0)$. Le segment rose d’un foyer à $(0, 3)$ mesure $a = 5$.|$a = 5$, $b = 3$: $c = 4$, focos $(\pm 4, 0)$. El segmento rosa de un foco a $(0, 3)$ mide $a = 5$.|$c = 4$、焦点 $(\pm 4, 0)$。|$c = 4$，焦点 $(\pm 4, 0)$。`,
      a: [Y(R`c = \sqrt{25 - 9} = 4`)] },
    { a: [F(R`\frac{x^2}{169} + \frac{y^2}{144} = 1`)],
      ex: { k: 'val', v: '5', q: R`The foci of $\tfrac{x^2}{169} + \tfrac{y^2}{144} = 1$ are $(\pm c, 0)$. Find $c$.|Les foyers de $\tfrac{x^2}{169} + \tfrac{y^2}{144} = 1$ sont $(\pm c, 0)$. Trouvez $c$.|Los focos de $\tfrac{x^2}{169} + \tfrac{y^2}{144} = 1$ son $(\pm c, 0)$. Halla $c$.|$\tfrac{x^2}{169} + \tfrac{y^2}{144} = 1$ の焦点 $(\pm c, 0)$ の $c$ を求めよ。|$\tfrac{x^2}{169} + \tfrac{y^2}{144} = 1$ 的焦点为 $(\pm c, 0)$，求 $c$。`, sol: [R`c^2 = 169 - 144 = 25`, R`c = 5`] } });

  lesson('Ellipse/Definition', 'Definition of the ellipse|Définition de l’ellipse|Definición de la elipse|楕円の定義|椭圆的定义',
    { s: R`An ellipse is the set of points whose distances to the two foci add up to a constant $2a$ — the gardener’s construction with two pins and a loop of string. So if you know one focal distance, the other is $2a$ minus it.|Une ellipse est l’ensemble des points dont la somme des distances aux deux foyers vaut une constante $2a$ — la construction du jardinier, avec deux piquets et une ficelle. Si l’on connaît une distance focale, l’autre vaut $2a$ moins elle.|Una elipse es el conjunto de puntos cuya suma de distancias a los dos focos es una constante $2a$: la construcción del jardinero con dos estacas y una cuerda. Si conoces una distancia focal, la otra es $2a$ menos ella.|楕円は 2 焦点までの距離の和が一定 $2a$ の点の集合（2 本のピンとひもで描く「庭師の方法」）。一方の距離がわかれば他方は $2a$ から引く。|椭圆是到两焦点距离之和为常数 $2a$ 的点集——园丁用两根桩和一根绳画椭圆。知道一个焦半径，另一个就是 $2a$ 减它。`,
      a: [Y(R`PF_1 + PF_2 = 2a`, { s: 30 }), EQ([-6, 6], [-4, 4]), ELL(5, 3), PTL(-4, 0, 'F₁', 'b'), PTL(4, 0, 'F₂', 'b'), SEGL(-4, 0, 3, 2.4, 'p'), SEGL(4, 0, 3, 2.4, 'p'), PTL(3, 2.4, 'P')] },
    { s: R`For $\tfrac{x^2}{25} + \tfrac{y^2}{9} = 1$ the sum is $2a = 10$. At $P(3, 2.4)$: $PF_1 = 7.4$ and $PF_2 = 2.6$, which add to 10.|Pour $\tfrac{x^2}{25} + \tfrac{y^2}{9} = 1$, la somme vaut 10. En $P(3 ; 2{,}4)$ : $PF_1 = 7{,}4$ et $PF_2 = 2{,}6$.|Para $\tfrac{x^2}{25} + \tfrac{y^2}{9} = 1$ la suma es 10. En $P(3;\ 2{,}4)$: $PF_1 = 7{,}4$ y $PF_2 = 2{,}6$.|和は 10：$7.4 + 2.6$。|和为 10：$7.4 + 2.6$。`,
      a: [Y(R`PF_1 + PF_2 = 7.4 + 2.6 = 10 = 2a`)] },
    { a: [F(R`\frac{x^2}{49} + \frac{y^2}{24} = 1,\quad PF_1 = 4`)],
      ex: { k: 'val', v: '10', q: R`$P$ is on $\tfrac{x^2}{49} + \tfrac{y^2}{24} = 1$ and $PF_1 = 4$. Find $PF_2$.|$P$ est sur $\tfrac{x^2}{49} + \tfrac{y^2}{24} = 1$ et $PF_1 = 4$. Calculez $PF_2$.|$P$ está en $\tfrac{x^2}{49} + \tfrac{y^2}{24} = 1$ y $PF_1 = 4$. Halla $PF_2$.|$P$ は $\tfrac{x^2}{49} + \tfrac{y^2}{24} = 1$ 上で $PF_1 = 4$。$PF_2$ を求めよ。|$P$ 在 $\tfrac{x^2}{49} + \tfrac{y^2}{24} = 1$ 上，$PF_1 = 4$，求 $PF_2$。`, sol: [R`2a = 14`, R`PF_2 = 14 - 4 = 10`] } });

  lesson('Ellipse/Eccentricity', 'Eccentricity of an ellipse|Excentricité d’une ellipse|Excentricidad de la elipse|楕円の離心率|椭圆的离心率',
    { s: R`$e = \tfrac ca$ measures how flat the ellipse is: $e = 0$ is a circle (foci at the centre), $e$ close to 1 is a long thin ellipse. Planet orbits have small $e$ (Earth: 0.017).|$e = \tfrac ca$ mesure l’aplatissement : $e = 0$ donne un cercle (foyers au centre), $e$ proche de 1 une ellipse longue et fine. Les orbites des planètes ont un petit $e$ (Terre : 0,017).|$e = \tfrac ca$ mide lo achatada que está: $e = 0$ es una circunferencia (focos en el centro) y $e$ cerca de 1 una elipse larga y estrecha. Las órbitas planetarias tienen $e$ pequeño (Tierra: 0,017).|$e = \tfrac ca$ は扁平さ：$e = 0$ は円、1 に近いほど細長い。惑星の軌道は $e$ が小さい（地球 0.017）。|$e = \tfrac ca$ 衡量扁平程度：$e = 0$ 是圆，接近 1 则细长。行星轨道 $e$ 很小（地球 0.017）。`,
      a: [Y(R`e = \frac ca,\quad 0 \le e < 1`, { s: 30 }), EQ([-6, 6], [-4, 4]), ELL(5, 4.5, 'b'), ELL(5, 3), ELL(5, 1.5, 'p')] },
    { s: R`$\tfrac{x^2}{25} + \tfrac{y^2}{9} = 1$: $c = 4$, $e = \tfrac45 = 0.8$ — quite flat.|$c = 4$, $e = 0{,}8$ — assez aplatie.|$c = 4$, $e = 0{,}8$: bastante achatada.|$e = 0.8$。|$e = 0.8$。`,
      a: [Y(R`e = \frac45 = 0.8`)] },
    { a: [F(R`\frac{x^2}{100} + \frac{y^2}{64} = 1`)],
      ex: { k: 'val', v: '0.6', q: R`Find the eccentricity of $\tfrac{x^2}{100} + \tfrac{y^2}{64} = 1$.|Calculez l’excentricité de $\tfrac{x^2}{100} + \tfrac{y^2}{64} = 1$.|Halla la excentricidad de $\tfrac{x^2}{100} + \tfrac{y^2}{64} = 1$.|$\tfrac{x^2}{100} + \tfrac{y^2}{64} = 1$ の離心率を求めよ。|求 $\tfrac{x^2}{100} + \tfrac{y^2}{64} = 1$ 的离心率。`, sol: [R`c = \sqrt{100 - 64} = 6`, R`e = \frac{6}{10} = 0.6`] } });

  lesson('Ellipse/Area and parametrisation', 'Area and parametrisation|Aire et paramétrage|Área y parametrización|面積と媒介変数表示|面积与参数方程',
    { s: R`Stretch the unit circle by $a$ horizontally and $b$ vertically: the point $(\cos t, \sin t)$ goes to $(a\cos t, b\sin t)$, and the area $\pi$ is multiplied by $ab$.|On étire le cercle unité de $a$ horizontalement et de $b$ verticalement : le point $(\cos t, \sin t)$ devient $(a\cos t, b\sin t)$, et l’aire $\pi$ est multipliée par $ab$.|Estira la circunferencia unidad $a$ en horizontal y $b$ en vertical: el punto $(\cos t, \sin t)$ pasa a $(a\cos t, b\sin t)$ y el área $\pi$ se multiplica por $ab$.|単位円を横に $a$、縦に $b$ 倍：$(\cos t, \sin t) \to (a\cos t, b\sin t)$、面積 $\pi$ は $ab$ 倍。|把单位圆水平拉伸 $a$、竖直拉伸 $b$：$(\cos t, \sin t)$ 变为 $(a\cos t, b\sin t)$，面积 $\pi$ 乘以 $ab$。`,
      a: [Y(R`S = \pi ab,\qquad (a\cos t,\ b\sin t)`), EQ([-6, 6], [-4, 4]), ELL(5, 3), IP('x^2+y^2=1', 'b'), PTL(2.5, 2.598, 't = 60°')] },
    { s: R`$\tfrac{x^2}{25} + \tfrac{y^2}{9} = 1$ has area $15\pi \approx 47.1$. At $t = 60°$ the point is $(5\cdot\tfrac12, 3\cdot\tfrac{\sqrt3}{2}) \approx (2.5, 2.6)$.|Aire $15\pi \approx 47{,}1$. En $t = 60°$ : $(2{,}5 ; 2{,}6)$.|Área $15\pi \approx 47{,}1$. En $t = 60°$: $(2{,}5;\ 2{,}6)$.|面積 $15\pi$。|面积 $15\pi$。`,
      a: [Y(R`S = \pi\cdot 5\cdot 3 = 15\pi`)] },
    { a: [F(R`\frac{x^2}{16} + \frac{y^2}{9} = 1`)],
      ex: { k: 'val', v: '12pi', q: R`Find the area enclosed by $\tfrac{x^2}{16} + \tfrac{y^2}{9} = 1$.|Calculez l’aire délimitée par $\tfrac{x^2}{16} + \tfrac{y^2}{9} = 1$.|Halla el área encerrada por $\tfrac{x^2}{16} + \tfrac{y^2}{9} = 1$.|$\tfrac{x^2}{16} + \tfrac{y^2}{9} = 1$ で囲まれた面積を求めよ。|求 $\tfrac{x^2}{16} + \tfrac{y^2}{9} = 1$ 围成的面积。`, sol: [R`a = 4,\ b = 3`, R`S = 12\pi \approx 37.7`] } });

  // =============================== Parabola ===============================
  lesson('Parabola/Equations', 'Equations of a parabola|Équations d’une parabole|Ecuaciones de la parábola|放物線の方程式|抛物线方程',
    { s: R`$x^2 = 4py$ opens upwards with focus $(0, p)$ and directrix $y = -p$; $y^2 = 4px$ opens to the right with focus $(p, 0)$ and directrix $x = -p$. Read $p$ by dividing the coefficient by 4.|$x^2 = 4py$ s’ouvre vers le haut, foyer $(0, p)$, directrice $y = -p$ ; $y^2 = 4px$ s’ouvre vers la droite, foyer $(p, 0)$, directrice $x = -p$. On lit $p$ en divisant le coefficient par 4.|$x^2 = 4py$ abre hacia arriba con foco $(0, p)$ y directriz $y = -p$; $y^2 = 4px$ abre a la derecha con foco $(p, 0)$ y directriz $x = -p$. Lee $p$ dividiendo el coeficiente entre 4.|$x^2 = 4py$ は上に開き焦点 $(0, p)$、準線 $y = -p$。$y^2 = 4px$ は右に開き焦点 $(p, 0)$、準線 $x = -p$。係数 ÷ 4 が $p$。|$x^2 = 4py$ 开口向上，焦点 $(0, p)$，准线 $y = -p$；$y^2 = 4px$ 开口向右，焦点 $(p, 0)$，准线 $x = -p$。系数除以 4 得 $p$。`,
      a: [Y(R`x^2 = 4py,\qquad y^2 = 4px`), EQ([-6, 6], [-3, 6]), P('x^2/8'), PTL(0, 2, 'F(0, 2)'), D2('-2')] },
    { s: R`$x^2 = 8y$: $4p = 8$, $p = 2$, focus $(0, 2)$, directrix $y = -2$.|$x^2 = 8y$ : $p = 2$, foyer $(0, 2)$, directrice $y = -2$.|$x^2 = 8y$: $p = 2$, foco $(0, 2)$, directriz $y = -2$.|$p = 2$、焦点 $(0, 2)$。|$p = 2$，焦点 $(0, 2)$。`,
      a: [Y(R`4p = 8 \Rightarrow p = 2`)] },
    { s: TRY_P, a: [F(R`y^2 = 12x`), EQ([-2, 8], [-6, 6]), IP('y^2=12x')],
      ex: { k: 'pt', v: [3, 0], q: R`Find the focus of $y^2 = 12x$.|Trouvez le foyer de $y^2 = 12x$.|Halla el foco de $y^2 = 12x$.|$y^2 = 12x$ の焦点を求めよ。|求 $y^2 = 12x$ 的焦点。`, sol: [R`4p = 12 \Rightarrow p = 3`, R`F(3, 0)`] } });

  lesson('Parabola/Definition', 'Definition of the parabola|Définition de la parabole|Definición de la parábola|放物線の定義|抛物线的定义',
    { s: R`Every point of a parabola is as far from the focus as from the directrix. So the distance to the focus is easy: for $y^2 = 4px$ it is the horizontal distance to the line $x = -p$, i.e. $x + p$.|Chaque point d’une parabole est aussi loin du foyer que de la directrice. La distance au foyer est donc facile : pour $y^2 = 4px$, c’est la distance horizontale à la droite $x = -p$, soit $x + p$.|Cada punto de una parábola está igual de lejos del foco que de la directriz. Así la distancia al foco es fácil: para $y^2 = 4px$ es la distancia horizontal a la recta $x = -p$, es decir $x + p$.|放物線上の点は焦点と準線から等距離。$y^2 = 4px$ なら焦点までの距離は準線 $x = -p$ までの横の距離 $x + p$。|抛物线上每点到焦点与到准线距离相等。所以到焦点的距离很好算：对 $y^2 = 4px$，就是到直线 $x = -p$ 的水平距离 $x + p$。`,
      a: [Y(R`PF = d(P, \ell)`, { s: 30 }), EQ([-3, 6], [-6, 6]), IP('y^2=8x'), PTL(2, 0, 'F', 'b'), VL2(-2), PTL(3, 4.899, 'P'), SEGL(3, 4.899, 2, 0, 'p'), SEGL(3, 4.899, -2, 4.899, 'p')] },
    { s: R`$y^2 = 8x$ ($p = 2$), point with $x = 3$: $PF = 3 + 2 = 5$ — no square roots needed.|$y^2 = 8x$ ($p = 2$), point d’abscisse 3 : $PF = 5$.|$y^2 = 8x$ ($p = 2$), punto con $x = 3$: $PF = 5$.|$PF = 3 + 2 = 5$。|$PF = 3 + 2 = 5$。`,
      a: [Y(R`PF = x + p = 3 + 2 = 5`)] },
    { a: [F(R`x^2 = 4y,\quad y_P = 6`)],
      ex: { k: 'val', v: '7', q: R`$P$ is on $x^2 = 4y$ with $y = 6$. Find its distance to the focus.|$P$ est sur $x^2 = 4y$ avec $y = 6$. Calculez sa distance au foyer.|$P$ está en $x^2 = 4y$ con $y = 6$. Halla su distancia al foco.|$x^2 = 4y$ 上で $y = 6$ の点 $P$ と焦点の距離を求めよ。|$P$ 在 $x^2 = 4y$ 上且 $y = 6$，求它到焦点的距离。`, sol: [R`p = 1,\ \text{directrix } y = -1`, R`PF = 6 + 1 = 7`] } });

  lesson('Parabola/Vertex form', 'Vertex form|Forme canonique|Forma canónica|頂点形|顶点式',
    { s: R`Complete the square to turn $ax^2 + bx + c$ into $a(x - h)^2 + k$; the vertex is $(h, k)$ and $h = -\tfrac{b}{2a}$. Then $\tfrac1a = 4p$ gives the focus, $p$ above the vertex when $a > 0$.|On complète le carré pour écrire $ax^2 + bx + c = a(x - h)^2 + k$ ; le sommet est $(h, k)$, avec $h = -\tfrac{b}{2a}$. Puis $\tfrac1a = 4p$ donne le foyer, à $p$ au-dessus du sommet si $a > 0$.|Completa el cuadrado para pasar $ax^2 + bx + c$ a $a(x - h)^2 + k$; el vértice es $(h, k)$ con $h = -\tfrac{b}{2a}$. Luego $\tfrac1a = 4p$ da el foco, a $p$ sobre el vértice si $a > 0$.|平方完成で $ax^2 + bx + c = a(x - h)^2 + k$、頂点 $(h, k)$、$h = -\tfrac{b}{2a}$。$\tfrac1a = 4p$ で焦点（$a > 0$ なら頂点の $p$ 上）。|配方把 $ax^2 + bx + c$ 化为 $a(x - h)^2 + k$；顶点 $(h, k)$，$h = -\tfrac{b}{2a}$。再由 $\tfrac1a = 4p$ 得焦点（$a > 0$ 时在顶点上方 $p$ 处）。`,
      a: [Y(R`y = a(x - h)^2 + k`, { s: 30 }), AX([-1, 5], [-4, 6]), P('2x^2-8x+5'), PTL(2, -3, '(2, −3)')] },
    { s: R`$y = 2x^2 - 8x + 5 = 2(x^2 - 4x + 4) - 8 + 5 = 2(x - 2)^2 - 3$: vertex $(2, -3)$.|$y = 2(x - 2)^2 - 3$ : sommet $(2, -3)$.|$y = 2(x - 2)^2 - 3$: vértice $(2, -3)$.|頂点 $(2, -3)$。|顶点 $(2, -3)$。`,
      a: [F(R`2(x^2 - 4x + 4) - 8 + 5`), Y(R`= 2(x - 2)^2 - 3`)] },
    { s: TRY_P, a: [F(R`y = x^2 + 6x + 1`)],
      ex: { k: 'pt', v: [-3, -8], q: R`Find the vertex of $y = x^2 + 6x + 1$.|Trouvez le sommet de $y = x^2 + 6x + 1$.|Halla el vértice de $y = x^2 + 6x + 1$.|$y = x^2 + 6x + 1$ の頂点を求めよ。|求 $y = x^2 + 6x + 1$ 的顶点。`, sol: [R`(x + 3)^2 - 9 + 1`, R`(-3,\ -8)`] } });

  lesson('Parabola/Eccentricity', 'Eccentricity of the parabola|Excentricité de la parabole|Excentricidad de la parábola|放物線の離心率|抛物线的离心率',
    { s: R`For every parabola $PF$ equals the distance to the directrix, so the ratio is exactly $e = 1$ — between the ellipse ($e < 1$) and the hyperbola ($e > 1$). All parabolas have the same shape; only the size $p$ changes.|Pour toute parabole $PF$ égale la distance à la directrice : le rapport vaut exactement $e = 1$ — entre l’ellipse ($e < 1$) et l’hyperbole ($e > 1$). Toutes les paraboles ont la même forme ; seule la taille $p$ change.|En toda parábola $PF$ es igual a la distancia a la directriz, así que el cociente es exactamente $e = 1$, entre la elipse ($e < 1$) y la hipérbola ($e > 1$). Todas las parábolas tienen la misma forma; solo cambia el tamaño $p$.|放物線では常に $PF$ = 準線までの距離なので $e = 1$（楕円 $e < 1$ と双曲線 $e > 1$ の間）。放物線はすべて相似で、大きさ $p$ だけが違う。|抛物线上 $PF$ 总等于到准线的距离，所以 $e = 1$——介于椭圆（$e < 1$）与双曲线（$e > 1$）之间。所有抛物线形状相同，只是大小 $p$ 不同。`,
      a: [Y(R`e = 1`, { s: 30 }), EQ([-6, 6], [-1, 8]), P('x^2/4'), P('x^2/12', 'b')] },
    { s: R`$y^2 = 4px$ through $(1, 2)$: $4 = 4p$, so $p = 1$, focus $(1, 0)$.|$y^2 = 4px$ par $(1, 2)$ : $p = 1$, foyer $(1, 0)$.|$y^2 = 4px$ por $(1, 2)$: $p = 1$, foco $(1, 0)$.|$p = 1$。|$p = 1$。`,
      a: [Y(R`4 = 4p\cdot 1 \Rightarrow p = 1`)] },
    { a: [F(R`y^2 = 4px\ \text{through}\ (2, 4)`)],
      ex: { k: 'val', v: '2', q: R`The parabola $y^2 = 4px$ passes through $(2, 4)$. Find $p$.|La parabole $y^2 = 4px$ passe par $(2, 4)$. Trouvez $p$.|La parábola $y^2 = 4px$ pasa por $(2, 4)$. Halla $p$.|放物線 $y^2 = 4px$ が $(2, 4)$ を通る。$p$ を求めよ。|抛物线 $y^2 = 4px$ 过 $(2, 4)$，求 $p$。`, sol: [R`16 = 8p`, R`p = 2`] } });

  // =============================== Hyperbola ===============================
  const HYP = (a, b, c = 'y') => IP(`x^2/${a * a}-y^2/${b * b}=1`, c);
  lesson('Hyperbola/Equation', 'Equation of a hyperbola|Équation d’une hyperbole|Ecuación de la hipérbola|双曲線の方程式|双曲线方程',
    { s: R`Same shape of equation as the ellipse but with a minus sign. It has two branches crossing the $x$-axis at $\pm a$ and never meets the $y$-axis; the distance between the vertices is $2a$.|Même forme d’équation que l’ellipse mais avec un signe moins. Deux branches coupent l’axe des $x$ en $\pm a$, sans jamais rencontrer l’axe des $y$ ; la distance entre les sommets vaut $2a$.|La misma forma de ecuación que la elipse pero con un signo menos. Tiene dos ramas que cortan el eje $x$ en $\pm a$ y nunca tocan el eje $y$; la distancia entre los vértices es $2a$.|楕円と同じ形の式でマイナス。2 本の枝が $x$ 軸と $\pm a$ で交わり、$y$ 軸とは交わらない。頂点間の距離は $2a$。|方程形式同椭圆，但为减号。两支与 $x$ 轴交于 $\pm a$，不与 $y$ 轴相交；两顶点距离为 $2a$。`,
      a: [Y(R`\frac{x^2}{a^2} - \frac{y^2}{b^2} = 1`), EQ([-8, 8], [-6, 6]), HYP(3, 4), PTL(3, 0, 'a'), PTL(-3, 0, '−a')] },
    { s: R`$\tfrac{x^2}{9} - \tfrac{y^2}{16} = 1$: $a = 3$, vertices $(\pm 3, 0)$. At $x = 0$: $-\tfrac{y^2}{16} = 1$ has no solution, so no $y$-intercept.|$a = 3$, sommets $(\pm 3, 0)$ ; pas d’intersection avec l’axe des $y$.|$a = 3$, vértices $(\pm 3, 0)$; no corta el eje $y$.|$a = 3$、$y$ 軸と交わらない。|$a = 3$，不与 $y$ 轴相交。`,
      a: [Y(R`a = 3:\ (\pm 3, 0)`)] },
    { a: [F(R`\frac{x^2}{16} - \frac{y^2}{9} = 1`)],
      ex: { k: 'val', v: '8', q: R`Find the distance between the vertices of $\tfrac{x^2}{16} - \tfrac{y^2}{9} = 1$.|Calculez la distance entre les sommets de $\tfrac{x^2}{16} - \tfrac{y^2}{9} = 1$.|Halla la distancia entre los vértices de $\tfrac{x^2}{16} - \tfrac{y^2}{9} = 1$.|$\tfrac{x^2}{16} - \tfrac{y^2}{9} = 1$ の頂点間の距離を求めよ。|求 $\tfrac{x^2}{16} - \tfrac{y^2}{9} = 1$ 两顶点间的距离。`, sol: [R`a = 4`, R`2a = 8`] } });

  lesson('Hyperbola/Foci', 'Foci of a hyperbola|Foyers d’une hyperbole|Focos de la hipérbola|双曲線の焦点|双曲线的焦点',
    { s: R`The foci are outside the vertices at $(\pm c, 0)$, and now the squares add: $c^2 = a^2 + b^2$. Compare the ellipse, where they subtract.|Les foyers sont au-delà des sommets en $(\pm c, 0)$, et cette fois les carrés s’ajoutent : $c^2 = a^2 + b^2$. Pour l’ellipse ils se soustraient.|Los focos están más allá de los vértices en $(\pm c, 0)$, y ahora los cuadrados se suman: $c^2 = a^2 + b^2$. En la elipse se restan.|焦点は頂点の外側 $(\pm c, 0)$ で、今度は $c^2 = a^2 + b^2$（楕円は引き算）。|焦点在顶点外侧 $(\pm c, 0)$，此时平方相加：$c^2 = a^2 + b^2$（椭圆是相减）。`,
      a: [Y(R`F_{1,2} = (\pm c, 0),\qquad c^2 = a^2 + b^2`), EQ([-8, 8], [-6, 6]), HYP(3, 4), PTL(5, 0, 'F₂', 'b'), PTL(-5, 0, 'F₁', 'b')] },
    { s: R`$a = 3$, $b = 4$: $c = \sqrt{9 + 16} = 5$, foci $(\pm 5, 0)$.|$a = 3$, $b = 4$ : $c = 5$, foyers $(\pm 5, 0)$.|$a = 3$, $b = 4$: $c = 5$, focos $(\pm 5, 0)$.|$c = 5$。|$c = 5$。`,
      a: [Y(R`c = \sqrt{9 + 16} = 5`)] },
    { a: [F(R`\frac{x^2}{7} - \frac{y^2}{9} = 1`)],
      ex: { k: 'val', v: '4', q: R`The foci of $\tfrac{x^2}{7} - \tfrac{y^2}{9} = 1$ are $(\pm c, 0)$. Find $c$.|Les foyers de $\tfrac{x^2}{7} - \tfrac{y^2}{9} = 1$ sont $(\pm c, 0)$. Trouvez $c$.|Los focos de $\tfrac{x^2}{7} - \tfrac{y^2}{9} = 1$ son $(\pm c, 0)$. Halla $c$.|$\tfrac{x^2}{7} - \tfrac{y^2}{9} = 1$ の焦点 $(\pm c, 0)$ の $c$ は？|$\tfrac{x^2}{7} - \tfrac{y^2}{9} = 1$ 的焦点为 $(\pm c, 0)$，求 $c$。`, sol: [R`c^2 = 7 + 9 = 16`, R`c = 4`] } });

  lesson('Hyperbola/Definition', 'Definition of the hyperbola|Définition de l’hyperbole|Definición de la hipérbola|双曲線の定義|双曲线的定义',
    { s: R`A hyperbola is the set of points whose distances to the two foci differ by the constant $2a$. On the right branch $PF_1 - PF_2 = 2a$, on the left branch the other way round — so one focal distance gives two possibilities for the other.|Une hyperbole est l’ensemble des points dont les distances aux deux foyers diffèrent de la constante $2a$. Sur la branche droite $PF_1 - PF_2 = 2a$, sur la gauche l’inverse — une distance focale donne donc deux possibilités pour l’autre.|Una hipérbola es el conjunto de puntos cuyas distancias a los focos difieren en la constante $2a$. En la rama derecha $PF_1 - PF_2 = 2a$ y en la izquierda al revés, así que una distancia focal da dos posibilidades para la otra.|双曲線は 2 焦点までの距離の差が一定 $2a$ の点の集合。右の枝では $PF_1 - PF_2 = 2a$、左では逆。だから一方の距離から他方は 2 通り考えられる。|双曲线是到两焦点距离之差为常数 $2a$ 的点集。右支上 $PF_1 - PF_2 = 2a$，左支相反——所以已知一个焦半径，另一个有两种可能。`,
      a: [Y(R`\lvert PF_1 - PF_2\rvert = 2a`, { s: 30 }), EQ([-8, 8], [-6, 6]), HYP(3, 4), PTL(-5, 0, 'F₁', 'b'), PTL(5, 0, 'F₂', 'b'), SEGL(-5, 0, 5, 5.333, 'p'), SEGL(5, 0, 5, 5.333, 'p'), PTL(5, 5.333, 'P')] },
    { s: R`$\tfrac{x^2}{9} - \tfrac{y^2}{16} = 1$: $2a = 6$. At $P(5, \tfrac{16}{3})$: $PF_2 = \tfrac{16}{3}$ and $PF_1 = \tfrac{34}{3}$, difference 6.|$2a = 6$. En $P(5, \tfrac{16}{3})$ : $PF_1 - PF_2 = \tfrac{34}{3} - \tfrac{16}{3} = 6$.|$2a = 6$. En $P(5, \tfrac{16}{3})$: $PF_1 - PF_2 = \tfrac{34}{3} - \tfrac{16}{3} = 6$.|差は 6。|差为 6。`,
      a: [Y(R`PF_1 - PF_2 = \frac{34}{3} - \frac{16}{3} = 6`)] },
    { s: TRY_R, a: [F(R`\frac{x^2}{16} - \frac{y^2}{9} = 1,\quad PF_1 = 11`)],
      ex: { k: 'roots', v: [3, 19], q: R`$P$ is on $\tfrac{x^2}{16} - \tfrac{y^2}{9} = 1$ and $PF_1 = 11$. Give both possible values of $PF_2$.|$P$ est sur $\tfrac{x^2}{16} - \tfrac{y^2}{9} = 1$ et $PF_1 = 11$. Donnez les deux valeurs possibles de $PF_2$.|$P$ está en $\tfrac{x^2}{16} - \tfrac{y^2}{9} = 1$ y $PF_1 = 11$. Da los dos valores posibles de $PF_2$.|$P$ は $\tfrac{x^2}{16} - \tfrac{y^2}{9} = 1$ 上で $PF_1 = 11$。$PF_2$ の 2 つの可能な値を答えよ。|$P$ 在 $\tfrac{x^2}{16} - \tfrac{y^2}{9} = 1$ 上，$PF_1 = 11$，求 $PF_2$ 的两个可能值。`, sol: [R`2a = 8`, R`PF_2 = 11 \pm 8 = 3\ \text{or}\ 19`] } });

  lesson('Hyperbola/Asymptotes', 'Asymptotes of a hyperbola|Asymptotes d’une hyperbole|Asíntotas de la hipérbola|双曲線の漸近線|双曲线的渐近线',
    { s: R`Far from the centre the 1 on the right becomes negligible, so $\tfrac{x^2}{a^2} \approx \tfrac{y^2}{b^2}$, i.e. $y \approx \pm\tfrac ba x$. The two asymptotes are the diagonals of the $2a \times 2b$ box around the centre.|Loin du centre le 1 devient négligeable : $\tfrac{x^2}{a^2} \approx \tfrac{y^2}{b^2}$, soit $y \approx \pm\tfrac ba x$. Les deux asymptotes sont les diagonales du rectangle $2a \times 2b$ autour du centre.|Lejos del centro el 1 se vuelve despreciable: $\tfrac{x^2}{a^2} \approx \tfrac{y^2}{b^2}$, es decir $y \approx \pm\tfrac ba x$. Las dos asíntotas son las diagonales del rectángulo $2a \times 2b$ alrededor del centro.|中心から遠いと右辺の 1 は無視でき $y \approx \pm\tfrac ba x$。漸近線は中心のまわりの $2a \times 2b$ の長方形の対角線。|远离中心时右边的 1 可忽略，$y \approx \pm\tfrac ba x$。两条渐近线是中心处 $2a \times 2b$ 矩形的对角线。`,
      a: [Y(R`y = \pm\frac ba\,x`, { s: 30 }), EQ([-8, 8], [-6, 6]), HYP(3, 4), D('4x/3', 'b'), D('-4x/3', 'b'), SEGL(-3, -4, 3, -4, 'g', { dash: true }), SEGL(3, -4, 3, 4, 'g', { dash: true }), SEGL(3, 4, -3, 4, 'g', { dash: true }), SEGL(-3, 4, -3, -4, 'g', { dash: true })] },
    { s: R`$\tfrac{x^2}{9} - \tfrac{y^2}{16} = 1$: asymptotes $y = \pm\tfrac43 x$, the diagonals of the $6 \times 8$ box.|Asymptotes $y = \pm\tfrac43 x$, diagonales du rectangle $6 \times 8$.|Asíntotas $y = \pm\tfrac43 x$, diagonales del rectángulo $6 \times 8$.|$y = \pm\tfrac43 x$。|$y = \pm\tfrac43 x$。`,
      a: [Y(R`y = \pm\frac43 x`)] },
    { a: [F(R`\frac{x^2}{25} - \frac{y^2}{4} = 1`)],
      ex: { k: 'val', v: '0.4', q: R`Find the positive slope of the asymptotes of $\tfrac{x^2}{25} - \tfrac{y^2}{4} = 1$.|Trouvez la pente positive des asymptotes de $\tfrac{x^2}{25} - \tfrac{y^2}{4} = 1$.|Halla la pendiente positiva de las asíntotas de $\tfrac{x^2}{25} - \tfrac{y^2}{4} = 1$.|$\tfrac{x^2}{25} - \tfrac{y^2}{4} = 1$ の漸近線の正の傾きを求めよ。|求 $\tfrac{x^2}{25} - \tfrac{y^2}{4} = 1$ 渐近线的正斜率。`, sol: [R`\frac ba = \frac25`, R`= 0.4`] } });

  lesson('Hyperbola/Eccentricity', 'Eccentricity of a hyperbola|Excentricité d’une hyperbole|Excentricidad de la hipérbola|双曲線の離心率|双曲线的离心率',
    { s: R`$e = \tfrac ca$ is now larger than 1 since $c > a$. The larger $e$, the more open the branches (steeper asymptotes, $\tfrac ba = \sqrt{e^2 - 1}$).|$e = \tfrac ca$ est maintenant supérieur à 1 car $c > a$. Plus $e$ est grand, plus les branches sont ouvertes (asymptotes plus raides, $\tfrac ba = \sqrt{e^2 - 1}$).|$e = \tfrac ca$ ahora es mayor que 1 porque $c > a$. Cuanto mayor $e$, más abiertas las ramas (asíntotas más inclinadas, $\tfrac ba = \sqrt{e^2 - 1}$).|$c > a$ なので $e = \tfrac ca > 1$。$e$ が大きいほど枝は開く（$\tfrac ba = \sqrt{e^2 - 1}$）。|因 $c > a$，$e = \tfrac ca > 1$。$e$ 越大，两支越张开（$\tfrac ba = \sqrt{e^2 - 1}$）。`,
      a: [Y(R`e = \frac ca > 1`, { s: 30 }), EQ([-8, 8], [-6, 6]), HYP(3, 1.5, 'b'), HYP(3, 4)] },
    { s: R`$\tfrac{x^2}{9} - \tfrac{y^2}{16} = 1$: $e = \tfrac53 \approx 1.67$.|$e = \tfrac53$.|$e = \tfrac53$.|$e = \tfrac53$。|$e = \tfrac53$。`,
      a: [Y(R`e = \frac53`)] },
    { a: [F(R`\frac{x^2}{16} - \frac{y^2}{9} = 1`)],
      ex: { k: 'val', v: '1.25', q: R`Find the eccentricity of $\tfrac{x^2}{16} - \tfrac{y^2}{9} = 1$.|Calculez l’excentricité de $\tfrac{x^2}{16} - \tfrac{y^2}{9} = 1$.|Halla la excentricidad de $\tfrac{x^2}{16} - \tfrac{y^2}{9} = 1$.|$\tfrac{x^2}{16} - \tfrac{y^2}{9} = 1$ の離心率を求めよ。|求 $\tfrac{x^2}{16} - \tfrac{y^2}{9} = 1$ 的离心率。`, sol: [R`c = 5`, R`e = \frac54 = 1.25`] } });

  lesson('Hyperbola/Rectangular hyperbola', 'Rectangular hyperbola|Hyperbole équilatère|Hipérbola equilátera|直角双曲線|等轴双曲线',
    { s: R`When $a = b$ the asymptotes are perpendicular. Turned by 45° such a hyperbola becomes $xy = k$: the axes themselves are the asymptotes. $y = \tfrac kx$ describes inverse proportion.|Quand $a = b$ les asymptotes sont perpendiculaires. Tournée de 45°, une telle hyperbole devient $xy = k$ : les axes sont les asymptotes. $y = \tfrac kx$ décrit la proportionnalité inverse.|Cuando $a = b$ las asíntotas son perpendiculares. Girada 45°, esa hipérbola es $xy = k$: los propios ejes son las asíntotas. $y = \tfrac kx$ describe la proporcionalidad inversa.|$a = b$ なら漸近線は直交。45° 回すと $xy = k$ で、座標軸が漸近線。$y = \tfrac kx$ は反比例。|$a = b$ 时渐近线垂直。旋转 45° 后变为 $xy = k$：坐标轴就是渐近线。$y = \tfrac kx$ 表示反比例。`,
      a: [Y(R`xy = k`, { s: 30 }), EQ([-6, 6], [-6, 6]), P('4/x'), PTL(2, 2, '(2, 2)'), PTL(-2, -2, '(−2, −2)')] },
    { s: R`$xy = 4$: vertices $(2, 2)$ and $(-2, -2)$ on the line $y = x$; as $x$ doubles, $y$ halves.|$xy = 4$ : sommets $(2, 2)$ et $(-2, -2)$ ; quand $x$ double, $y$ est divisé par deux.|$xy = 4$: vértices $(2, 2)$ y $(-2, -2)$; si $x$ se duplica, $y$ se reduce a la mitad.|頂点 $(\pm 2, \pm 2)$。|顶点 $(\pm 2, \pm 2)$。`,
      a: [Y(R`x = y \Rightarrow x^2 = 4 \Rightarrow (\pm 2, \pm 2)`)] },
    { a: [F(R`xy = k\ \text{through}\ (3, 4)`)],
      ex: { k: 'val', v: '12', q: R`The hyperbola $xy = k$ passes through $(3, 4)$. Find $k$.|L’hyperbole $xy = k$ passe par $(3, 4)$. Trouvez $k$.|La hipérbola $xy = k$ pasa por $(3, 4)$. Halla $k$.|$xy = k$ が $(3, 4)$ を通る。$k$ を求めよ。|$xy = k$ 过 $(3, 4)$，求 $k$。`, sol: [R`k = 3\cdot 4 = 12`] } });

  // =============================== Tangents and chords of conics ===============================
  lesson('Tangents and chords of conics/Ellipse tangent at (x₀, y₀)', 'Tangent to an ellipse|Tangente à une ellipse|Tangente a una elipse|楕円の接線|椭圆的切线',
    { s: R`The same “doubling” rule as for the circle: replace $x^2$ by $x x_0$ and $y^2$ by $y y_0$. The point must lie on the ellipse for this to be a tangent.|Même règle de « dédoublement » que pour le cercle : on remplace $x^2$ par $x x_0$ et $y^2$ par $y y_0$. Le point doit être sur l’ellipse.|La misma regla de «desdoblamiento» que en la circunferencia: cambia $x^2$ por $x x_0$ e $y^2$ por $y y_0$. El punto debe estar en la elipse.|円と同じ置き換え：$x^2 \to x x_0$、$y^2 \to y y_0$。点は楕円上にあること。|与圆相同的“分写”规则：$x^2 \to x x_0$，$y^2 \to y y_0$。点必须在椭圆上。`,
      a: [Y(R`\frac{x x_0}{a^2} + \frac{y y_0}{b^2} = 1`), EQ([-6, 7], [-4, 6]), ELL(5, 3), P('5-4x/5', 'b'), PTL(4, 1.8, '(4, 9/5)')] },
    { s: R`$\tfrac{x^2}{25} + \tfrac{y^2}{9} = 1$ at $(4, \tfrac95)$: $\tfrac{4x}{25} + \tfrac{y}{5} = 1$, i.e. $y = 5 - \tfrac45 x$.|En $(4, \tfrac95)$ : $\tfrac{4x}{25} + \tfrac y5 = 1$, soit $y = 5 - \tfrac45 x$.|En $(4, \tfrac95)$: $\tfrac{4x}{25} + \tfrac y5 = 1$, es decir $y = 5 - \tfrac45 x$.|$y = 5 - \tfrac45 x$。|$y = 5 - \tfrac45 x$。`,
      a: [F(R`\frac{4x}{25} + \frac{(9/5)y}{9} = 1`), Y(R`y = 5 - \tfrac45 x`)] },
    { s: TRY_E, a: [F(R`\frac{x^2}{8} + \frac{y^2}{2} = 1,\quad (2, 1)`)],
      ex: { k: 'expr', f: '2-x/2', q: R`Find the tangent to $\tfrac{x^2}{8} + \tfrac{y^2}{2} = 1$ at $(2, 1)$.|Trouvez la tangente à $\tfrac{x^2}{8} + \tfrac{y^2}{2} = 1$ en $(2, 1)$.|Halla la tangente a $\tfrac{x^2}{8} + \tfrac{y^2}{2} = 1$ en $(2, 1)$.|$\tfrac{x^2}{8} + \tfrac{y^2}{2} = 1$ の $(2, 1)$ での接線を求めよ。|求 $\tfrac{x^2}{8} + \tfrac{y^2}{2} = 1$ 在 $(2, 1)$ 处的切线。`, sol: [R`\frac{2x}{8} + \frac{y}{2} = 1`, R`y = 2 - \frac x2`] } });

  lesson('Tangents and chords of conics/Hyperbola tangent at (x₀, y₀)', 'Tangent to a hyperbola|Tangente à une hyperbole|Tangente a una hipérbola|双曲線の接線|双曲线的切线',
    { s: R`Again double the variables: $x^2 \to x x_0$, $y^2 \to y y_0$, keeping the minus sign. The tangent at a vertex is vertical; far out it approaches an asymptote.|On dédouble encore : $x^2 \to x x_0$, $y^2 \to y y_0$, en gardant le signe moins. La tangente en un sommet est verticale ; loin, elle se rapproche d’une asymptote.|De nuevo se desdobla: $x^2 \to x x_0$, $y^2 \to y y_0$, conservando el signo menos. En un vértice la tangente es vertical; lejos se acerca a una asíntota.|同じく $x^2 \to x x_0$、$y^2 \to y y_0$（マイナスはそのまま）。頂点での接線は垂直、遠くでは漸近線に近づく。|同样分写：$x^2 \to x x_0$，$y^2 \to y y_0$，保留减号。顶点处切线竖直；远处接近渐近线。`,
      a: [Y(R`\frac{x x_0}{a^2} - \frac{y y_0}{b^2} = 1`), EQ([-8, 8], [-6, 8]), HYP(3, 4), P('5x/3-3', 'b'), PTL(5, 5.333, '(5, 16/3)')] },
    { s: R`$\tfrac{x^2}{9} - \tfrac{y^2}{16} = 1$ at $(5, \tfrac{16}{3})$: $\tfrac{5x}{9} - \tfrac{y}{3} = 1$, i.e. $y = \tfrac53 x - 3$.|En $(5, \tfrac{16}{3})$ : $\tfrac{5x}{9} - \tfrac y3 = 1$, soit $y = \tfrac53 x - 3$.|En $(5, \tfrac{16}{3})$: $\tfrac{5x}{9} - \tfrac y3 = 1$, es decir $y = \tfrac53 x - 3$.|$y = \tfrac53 x - 3$。|$y = \tfrac53 x - 3$。`,
      a: [Y(R`y = \tfrac53 x - 3`)] },
    { s: TRY_E, a: [F(R`\frac{x^2}{4} - \frac{y^2}{3} = 1,\quad (4, 3)`)],
      ex: { k: 'expr', f: 'x-1', q: R`Find the tangent to $\tfrac{x^2}{4} - \tfrac{y^2}{3} = 1$ at $(4, 3)$.|Trouvez la tangente à $\tfrac{x^2}{4} - \tfrac{y^2}{3} = 1$ en $(4, 3)$.|Halla la tangente a $\tfrac{x^2}{4} - \tfrac{y^2}{3} = 1$ en $(4, 3)$.|$\tfrac{x^2}{4} - \tfrac{y^2}{3} = 1$ の $(4, 3)$ での接線を求めよ。|求 $\tfrac{x^2}{4} - \tfrac{y^2}{3} = 1$ 在 $(4, 3)$ 处的切线。`, sol: [R`\frac{4x}{4} - \frac{3y}{3} = 1`, R`y = x - 1`] } });

  lesson('Tangents and chords of conics/Parabola tangent at (x₀, y₀)', 'Tangent to a parabola|Tangente à une parabole|Tangente a una parábola|放物線の接線|抛物线的切线',
    { s: R`Doubling for a parabola: $y^2 \to y y_0$ and the linear term $x \to \tfrac{x + x_0}{2}$. For $y^2 = 4px$ that gives $y y_0 = 2p(x + x_0)$.|Dédoublement pour une parabole : $y^2 \to y y_0$ et le terme linéaire $x \to \tfrac{x + x_0}{2}$. Pour $y^2 = 4px$ : $y y_0 = 2p(x + x_0)$.|Desdoblamiento en la parábola: $y^2 \to y y_0$ y el término lineal $x \to \tfrac{x + x_0}{2}$. Para $y^2 = 4px$: $y y_0 = 2p(x + x_0)$.|放物線では $y^2 \to y y_0$、1 次の項 $x \to \tfrac{x + x_0}{2}$。$y^2 = 4px$ なら $y y_0 = 2p(x + x_0)$。|抛物线的分写：$y^2 \to y y_0$，一次项 $x \to \tfrac{x + x_0}{2}$。对 $y^2 = 4px$ 得 $y y_0 = 2p(x + x_0)$。`,
      a: [Y(R`y^2 = 4px:\ y y_0 = 2p(x + x_0)`), EQ([-3, 7], [-6, 7]), IP('y^2=8x'), P('x+2', 'b'), PTL(2, 4, '(2, 4)')] },
    { s: R`$y^2 = 8x$ ($p = 2$) at $(2, 4)$: $4y = 4(x + 2)$, i.e. $y = x + 2$. It meets the axis at $x = -2$: the tangent at $(x_0, y_0)$ always crosses the axis at $-x_0$.|$y^2 = 8x$ en $(2, 4)$ : $4y = 4(x + 2)$, soit $y = x + 2$.|$y^2 = 8x$ en $(2, 4)$: $4y = 4(x + 2)$, es decir $y = x + 2$.|$y = x + 2$。|$y = x + 2$。`,
      a: [Y(R`4y = 4(x + 2) \Rightarrow y = x + 2`)] },
    { s: TRY_E, a: [F(R`x^2 = 4y,\quad (4, 4)`)],
      ex: { k: 'expr', f: '2x-4', q: R`Find the tangent to $x^2 = 4y$ at $(4, 4)$.|Trouvez la tangente à $x^2 = 4y$ en $(4, 4)$.|Halla la tangente a $x^2 = 4y$ en $(4, 4)$.|$x^2 = 4y$ の $(4, 4)$ での接線を求めよ。|求 $x^2 = 4y$ 在 $(4, 4)$ 处的切线。`, sol: [R`p = 1:\ 4x = 2(y + 4)`, R`y = 2x - 4`] } });

  lesson('Tangents and chords of conics/Tangency condition', 'When is a line tangent?|Condition de tangence|Condición de tangencia|接する条件|相切条件',
    { s: R`Substitute $y = mx + c$ into the ellipse: you get a quadratic in $x$. The line is tangent when that quadratic has a double root (discriminant 0), which simplifies to $c^2 = a^2m^2 + b^2$. For a given slope there are two tangents, $c = \pm\sqrt{a^2m^2 + b^2}$.|On remplace $y = mx + c$ dans l’ellipse : on obtient une équation du second degré en $x$. La droite est tangente quand elle a une racine double (discriminant nul), ce qui donne $c^2 = a^2m^2 + b^2$. Pour une pente donnée il y a deux tangentes, $c = \pm\sqrt{a^2m^2 + b^2}$.|Sustituye $y = mx + c$ en la elipse: sale una cuadrática en $x$. La recta es tangente cuando tiene raíz doble (discriminante 0), lo que da $c^2 = a^2m^2 + b^2$. Para una pendiente dada hay dos tangentes, $c = \pm\sqrt{a^2m^2 + b^2}$.|$y = mx + c$ を代入すると $x$ の 2 次方程式。重解（判別式 0）なら接し、$c^2 = a^2m^2 + b^2$。同じ傾きで接線は 2 本 $c = \pm\sqrt{a^2m^2 + b^2}$。|把 $y = mx + c$ 代入椭圆得 $x$ 的二次方程。有重根（判别式为 0）时相切，化简得 $c^2 = a^2m^2 + b^2$。给定斜率有两条切线 $c = \pm\sqrt{a^2m^2 + b^2}$。`,
      a: [Y(R`c^2 = a^2m^2 + b^2`, { s: 30 }), EQ([-4, 4], [-4, 4]), ELL(2, 1), P('x+2.2361', 'b'), P('x-2.2361', 'b')] },
    { s: R`$\tfrac{x^2}{4} + y^2 = 1$ with slope 1: $c^2 = 4 + 1 = 5$, so $y = x \pm\sqrt5$ — the two blue lines.|$\tfrac{x^2}{4} + y^2 = 1$, pente 1 : $c^2 = 5$, d’où $y = x \pm\sqrt5$.|$\tfrac{x^2}{4} + y^2 = 1$, pendiente 1: $c^2 = 5$, así que $y = x \pm\sqrt5$.|$c = \pm\sqrt5$。|$c = \pm\sqrt5$。`,
      a: [Y(R`c^2 = 4\cdot 1 + 1 = 5 \Rightarrow c = \pm\sqrt5`)] },
    { s: TRY_R, a: [F(R`\frac{x^2}{9} + \frac{y^2}{16} = 1,\quad m = 1`)],
      ex: { k: 'roots', v: [5, -5], q: R`Find the values of $c$ for which $y = x + c$ is tangent to $\tfrac{x^2}{9} + \tfrac{y^2}{16} = 1$.|Trouvez les valeurs de $c$ pour lesquelles $y = x + c$ est tangente à $\tfrac{x^2}{9} + \tfrac{y^2}{16} = 1$.|Halla los valores de $c$ para los que $y = x + c$ es tangente a $\tfrac{x^2}{9} + \tfrac{y^2}{16} = 1$.|$y = x + c$ が $\tfrac{x^2}{9} + \tfrac{y^2}{16} = 1$ に接する $c$ を求めよ。|求使 $y = x + c$ 与 $\tfrac{x^2}{9} + \tfrac{y^2}{16} = 1$ 相切的 $c$。`, sol: [R`c^2 = 9\cdot 1 + 16 = 25`, R`c = \pm 5`] } });

  lesson('Tangents and chords of conics/Latus rectum', 'The latus rectum|Le paramètre (corde focale)|El lado recto|通径|通径',
    { s: R`The latus rectum is the chord through a focus perpendicular to the major axis. Put $x = c$ into the equation: $y = \pm\tfrac{b^2}{a}$, so its length is $\tfrac{2b^2}{a}$ for the ellipse and the hyperbola; for $y^2 = 4px$, $x = p$ gives $y = \pm 2p$, length $4p$.|Le paramètre est la corde passant par un foyer perpendiculairement au grand axe. Avec $x = c$ : $y = \pm\tfrac{b^2}{a}$, longueur $\tfrac{2b^2}{a}$ pour l’ellipse et l’hyperbole ; pour $y^2 = 4px$, $x = p$ donne $y = \pm 2p$, longueur $4p$.|El lado recto es la cuerda que pasa por un foco perpendicular al eje mayor. Con $x = c$: $y = \pm\tfrac{b^2}{a}$, longitud $\tfrac{2b^2}{a}$ en elipse e hipérbola; en $y^2 = 4px$, $x = p$ da $y = \pm 2p$, longitud $4p$.|通径は焦点を通り長軸に垂直な弦。$x = c$ を代入すると $y = \pm\tfrac{b^2}{a}$ で長さ $\tfrac{2b^2}{a}$。$y^2 = 4px$ では長さ $4p$。|通径是过焦点且垂直于长轴的弦。代入 $x = c$ 得 $y = \pm\tfrac{b^2}{a}$，长 $\tfrac{2b^2}{a}$；对 $y^2 = 4px$ 长为 $4p$。`,
      a: [Y(R`\frac{2b^2}{a}\ (E, H),\qquad 4p\ (y^2 = 4px)`), EQ([-6, 6], [-4, 4]), ELL(5, 3), SEGL(4, -1.8, 4, 1.8, 'p', { w: 3 }), PTL(4, 0, 'F', 'b')] },
    { s: R`$\tfrac{x^2}{25} + \tfrac{y^2}{9} = 1$: $\tfrac{2\cdot 9}{5} = 3.6$ — the pink chord from $(4, -1.8)$ to $(4, 1.8)$.|$\tfrac{2\cdot 9}{5} = 3{,}6$ — la corde rose de $(4 ; -1{,}8)$ à $(4 ; 1{,}8)$.|$\tfrac{2\cdot 9}{5} = 3{,}6$: la cuerda rosa de $(4;\ -1{,}8)$ a $(4;\ 1{,}8)$.|$3.6$。|$3.6$。`,
      a: [Y(R`\frac{2\cdot 9}{5} = 3.6`)] },
    { a: [F(R`\frac{x^2}{9} - \frac{y^2}{16} = 1`)],
      ex: { k: 'val', v: '32/3', q: R`Find the length of the latus rectum of $\tfrac{x^2}{9} - \tfrac{y^2}{16} = 1$.|Calculez la longueur du paramètre de $\tfrac{x^2}{9} - \tfrac{y^2}{16} = 1$.|Halla la longitud del lado recto de $\tfrac{x^2}{9} - \tfrac{y^2}{16} = 1$.|$\tfrac{x^2}{9} - \tfrac{y^2}{16} = 1$ の通径の長さを求めよ。|求 $\tfrac{x^2}{9} - \tfrac{y^2}{16} = 1$ 的通径长。`, sol: [R`\frac{2\cdot 16}{3}`, R`= \frac{32}{3} \approx 10.67`] } });

  lesson('Tangents and chords of conics/Focal chord of a parabola', 'Focal chords of a parabola|Cordes focales d’une parabole|Cuerdas focales de la parábola|放物線の焦点弦|抛物线的焦点弦',
    { s: R`By the definition, each endpoint’s distance to the focus is its distance to the directrix, $x + p$. A chord through the focus is made of two such pieces, so its length is $x_1 + x_2 + 2p$ — just add.|Par définition, la distance de chaque extrémité au foyer est sa distance à la directrice, $x + p$. Une corde passant par le foyer est formée de deux tels morceaux : sa longueur est $x_1 + x_2 + 2p$.|Por la definición, la distancia de cada extremo al foco es su distancia a la directriz, $x + p$. Una cuerda por el foco está formada por dos trozos así, de modo que mide $x_1 + x_2 + 2p$.|定義より、端点と焦点の距離は準線までの距離 $x + p$。焦点を通る弦はその 2 つの和で長さ $x_1 + x_2 + 2p$。|由定义，每个端点到焦点的距离等于到准线的距离 $x + p$。过焦点的弦由两段组成，长为 $x_1 + x_2 + 2p$。`,
      a: [Y(R`\lvert AB\rvert = x_1 + x_2 + 2p,\qquad PF = x_0 + p`, { s: 24 }), EQ([-3, 6], [-6, 6]), IP('y^2=8x'), SEGL(1, -2.828, 4, 5.657, 'p'), PTL(2, 0, 'F', 'b'), PTL(1, -2.828, 'A'), PTL(4, 5.657, 'B')] },
    { s: R`$y^2 = 8x$ ($p = 2$), focal chord with endpoints at $x = 1$ and $x = 4$: $\lvert AB\rvert = 1 + 4 + 4 = 9$.|$y^2 = 8x$, extrémités en $x = 1$ et $x = 4$ : $\lvert AB\rvert = 9$.|$y^2 = 8x$, extremos en $x = 1$ y $x = 4$: $\lvert AB\rvert = 9$.|$\lvert AB\rvert = 9$。|$\lvert AB\rvert = 9$。`,
      a: [Y(R`\lvert AB\rvert = 1 + 4 + 2\cdot 2 = 9`)] },
    { a: [F(R`y^2 = 12x,\quad x_1 = 2,\ x_2 = 4.5`)],
      ex: { k: 'val', v: '12.5', q: R`A focal chord of $y^2 = 12x$ has endpoints with $x_1 = 2$ and $x_2 = 4.5$. Find its length.|Une corde focale de $y^2 = 12x$ a des extrémités d’abscisses 2 et 4,5. Calculez sa longueur.|Una cuerda focal de $y^2 = 12x$ tiene extremos con $x_1 = 2$ y $x_2 = 4{,}5$. Halla su longitud.|$y^2 = 12x$ の焦点弦の端点の $x$ 座標が 2 と 4.5。長さを求めよ。|$y^2 = 12x$ 的焦点弦端点横坐标为 2 和 4.5，求其长。`, sol: [R`p = 3`, R`2 + 4.5 + 6 = 12.5`] } });

  lesson('Tangents and chords of conics/Focal distances of an ellipse', 'Focal distances on an ellipse|Distances focales sur une ellipse|Distancias focales en la elipse|楕円の焦点距離|椭圆的焦半径',
    { s: R`For a point of the ellipse with abscissa $x_0$, the distances to the foci are linear in $x_0$: $a + e x_0$ to the left focus and $a - e x_0$ to the right one. They add to $2a$, as the definition demands.|Pour un point de l’ellipse d’abscisse $x_0$, les distances aux foyers sont affines en $x_0$ : $a + e x_0$ au foyer gauche et $a - e x_0$ au foyer droit. Leur somme vaut $2a$, comme l’exige la définition.|Para un punto de la elipse con abscisa $x_0$, las distancias a los focos son lineales en $x_0$: $a + e x_0$ al foco izquierdo y $a - e x_0$ al derecho. Suman $2a$, como exige la definición.|$x$ 座標 $x_0$ の点では焦点までの距離は 1 次式：左焦点 $a + e x_0$、右焦点 $a - e x_0$。和は $2a$。|横坐标为 $x_0$ 的点到焦点的距离是 $x_0$ 的一次式：左焦点 $a + e x_0$，右焦点 $a - e x_0$，和为 $2a$。`,
      a: [Y(R`PF_1 = a + e\,x_0,\qquad PF_2 = a - e\,x_0`), EQ([-6, 6], [-4, 4]), ELL(5, 3), PTL(-4, 0, 'F₁', 'b'), PTL(4, 0, 'F₂', 'b'), SEGL(-4, 0, 3, 2.4, 'p'), SEGL(4, 0, 3, 2.4, 'p'), PTL(3, 2.4, 'P')] },
    { s: R`$a = 5$, $e = 0.8$, $x_0 = 3$: $PF_1 = 5 + 2.4 = 7.4$, $PF_2 = 5 - 2.4 = 2.6$ — the same as computed with the distance formula.|$a = 5$, $e = 0{,}8$, $x_0 = 3$ : $PF_1 = 7{,}4$, $PF_2 = 2{,}6$.|$a = 5$, $e = 0{,}8$, $x_0 = 3$: $PF_1 = 7{,}4$, $PF_2 = 2{,}6$.|$7.4$ と $2.6$。|$7.4$ 与 $2.6$。`,
      a: [Y(R`PF_1 = 7.4,\quad PF_2 = 2.6`)] },
    { a: [F(R`\frac{x^2}{25} + \frac{y^2}{16} = 1,\quad x_0 = 2`)],
      ex: { k: 'val', v: '6.2', q: R`$P$ is on $\tfrac{x^2}{25} + \tfrac{y^2}{16} = 1$ with $x_0 = 2$. Find $PF_1$, the distance to the left focus.|$P$ est sur $\tfrac{x^2}{25} + \tfrac{y^2}{16} = 1$ avec $x_0 = 2$. Calculez $PF_1$, la distance au foyer gauche.|$P$ está en $\tfrac{x^2}{25} + \tfrac{y^2}{16} = 1$ con $x_0 = 2$. Halla $PF_1$, la distancia al foco izquierdo.|$\tfrac{x^2}{25} + \tfrac{y^2}{16} = 1$ 上で $x_0 = 2$ の点の左焦点までの距離 $PF_1$ を求めよ。|$P$ 在 $\tfrac{x^2}{25} + \tfrac{y^2}{16} = 1$ 上，$x_0 = 2$，求到左焦点的距离 $PF_1$。`, sol: [R`c = 3,\ e = 0.6`, R`PF_1 = 5 + 0.6\cdot 2 = 6.2`] } });

  lesson('Tangents and chords of conics/Chord with a given midpoint', 'Chord with a given midpoint|Corde de milieu donné|Cuerda con punto medio dado|中点が与えられた弦|已知中点的弦',
    { s: R`Write the ellipse equation for both endpoints and subtract: the differences factor as $(x_1 - x_2)(x_1 + x_2)$, and $x_1 + x_2 = 2x_0$. Dividing gives the slope of the chord in terms of the midpoint alone (the “point difference” method).|On écrit l’équation de l’ellipse pour les deux extrémités et on soustrait : les différences se factorisent en $(x_1 - x_2)(x_1 + x_2)$, avec $x_1 + x_2 = 2x_0$. En divisant on obtient la pente de la corde en fonction du seul milieu (méthode des différences).|Escribe la ecuación de la elipse para los dos extremos y resta: las diferencias se factorizan como $(x_1 - x_2)(x_1 + x_2)$, con $x_1 + x_2 = 2x_0$. Al dividir sale la pendiente de la cuerda solo en función del punto medio.|両端点で楕円の式を書いて引くと $(x_1 - x_2)(x_1 + x_2)$ に因数分解され、$x_1 + x_2 = 2x_0$。割ると中点だけで弦の傾きが出る（点差法）。|对两个端点写出椭圆方程相减：差分解为 $(x_1 - x_2)(x_1 + x_2)$，且 $x_1 + x_2 = 2x_0$。相除得只用中点表示的弦斜率（点差法）。`,
      a: [Y(R`m_{AB} = -\frac{b^2 x_0}{a^2 y_0}`, { s: 30 }), EQ([-5, 5], [-4, 4]), ELL(4, 3), P('-9x/8+13/4', 'b'), PTL(2, 1, 'M(2, 1)')] },
    { s: R`$\tfrac{x^2}{16} + \tfrac{y^2}{9} = 1$, midpoint $(2, 1)$: $m = -\tfrac{9\cdot 2}{16\cdot 1} = -\tfrac98$, so the chord is $y - 1 = -\tfrac98(x - 2)$.|Milieu $(2, 1)$ : $m = -\tfrac98$, corde $y - 1 = -\tfrac98(x - 2)$.|Punto medio $(2, 1)$: $m = -\tfrac98$, cuerda $y - 1 = -\tfrac98(x - 2)$.|$m = -\tfrac98$。|$m = -\tfrac98$。`,
      a: [Y(R`m = -\frac{9\cdot 2}{16\cdot 1} = -\frac98`)] },
    { a: [F(R`\frac{x^2}{4} + \frac{y^2}{2} = 1,\quad M(1, 1)`)],
      ex: { k: 'val', v: '-0.5', q: R`A chord of $\tfrac{x^2}{4} + \tfrac{y^2}{2} = 1$ has midpoint $(1, 1)$. Find its slope.|Une corde de $\tfrac{x^2}{4} + \tfrac{y^2}{2} = 1$ a pour milieu $(1, 1)$. Trouvez sa pente.|Una cuerda de $\tfrac{x^2}{4} + \tfrac{y^2}{2} = 1$ tiene punto medio $(1, 1)$. Halla su pendiente.|$\tfrac{x^2}{4} + \tfrac{y^2}{2} = 1$ の弦の中点が $(1, 1)$。傾きを求めよ。|$\tfrac{x^2}{4} + \tfrac{y^2}{2} = 1$ 的弦中点为 $(1, 1)$，求斜率。`, sol: [R`m = -\frac{2\cdot 1}{4\cdot 1}`, R`= -\frac12`] } });

  // =============================== Conics in general ===============================
  lesson('Conics in general/Classification', 'Classifying a conic|Classer une conique|Clasificar una cónica|2 次曲線の分類|二次曲线的分类',
    { s: R`The quadratic part $Ax^2 + Bxy + Cy^2$ decides the type through $B^2 - 4AC$: negative — ellipse (or circle); zero — parabola; positive — hyperbola. The linear terms only move the curve. (Degenerate cases — a point, two lines, nothing — can also occur.)|La partie quadratique $Ax^2 + Bxy + Cy^2$ décide du type via $B^2 - 4AC$ : négatif — ellipse (ou cercle) ; nul — parabole ; positif — hyperbole. Les termes du premier degré ne font que déplacer la courbe. (Des cas dégénérés — un point, deux droites, rien — existent aussi.)|La parte cuadrática $Ax^2 + Bxy + Cy^2$ decide el tipo mediante $B^2 - 4AC$: negativo, elipse (o circunferencia); cero, parábola; positivo, hipérbola. Los términos lineales solo la desplazan. (También hay casos degenerados: un punto, dos rectas, nada.)|2 次の部分 $Ax^2 + Bxy + Cy^2$ の $B^2 - 4AC$ で種類が決まる：負なら楕円（円）、0 なら放物線、正なら双曲線。1 次の項は位置を変えるだけ（点、2 直線、空集合などの退化もある）。|二次部分 $Ax^2 + Bxy + Cy^2$ 由 $B^2 - 4AC$ 决定类型：负——椭圆（或圆）；零——抛物线；正——双曲线。一次项只移动曲线。（也有退化情形：一点、两直线、空集。）`,
      a: [Y(R`B^2 - 4AC:\quad < 0\ \text{E},\quad = 0\ \text{P},\quad > 0\ \text{H}`, { s: 22 }), EQ([-4, 4], [-4, 4]), IP('x^2+x*y+y^2=3')] },
    { s: R`$x^2 + xy + y^2 = 3$: $B^2 - 4AC = 1 - 4 = -3 < 0$, an ellipse tilted at 45°.|$x^2 + xy + y^2 = 3$ : $1 - 4 = -3 < 0$, une ellipse inclinée de 45°.|$x^2 + xy + y^2 = 3$: $1 - 4 = -3 < 0$, una elipse inclinada 45°.|$-3 < 0$ で楕円。|$-3 < 0$，椭圆。`,
      a: [Y(R`1^2 - 4\cdot 1\cdot 1 = -3 < 0\ \Rightarrow\ \text{ellipse}`)] },
    { a: [F(R`x^2 + 3xy + y^2 = 5`), EQ([-6, 6], [-6, 6]), IP('x^2+3x*y+y^2=5')],
      ex: { k: 'val', v: '5', q: R`Compute $B^2 - 4AC$ for $x^2 + 3xy + y^2 = 5$ (the curve is a hyperbola).|Calculez $B^2 - 4AC$ pour $x^2 + 3xy + y^2 = 5$ (la courbe est une hyperbole).|Calcula $B^2 - 4AC$ para $x^2 + 3xy + y^2 = 5$ (la curva es una hipérbola).|$x^2 + 3xy + y^2 = 5$ の $B^2 - 4AC$ を求めよ（双曲線）。|计算 $x^2 + 3xy + y^2 = 5$ 的 $B^2 - 4AC$（曲线为双曲线）。`, sol: [R`9 - 4\cdot 1\cdot 1`, R`= 5 > 0`] } });

  lesson('Conics in general/Focus–directrix', 'Focus and directrix|Foyer et directrice|Foco y directriz|焦点と準線|焦点与准线',
    { s: R`Every conic (except the circle) is the set of points whose distance to a focus is $e$ times the distance to a line, the directrix. $e < 1$ gives an ellipse, $e = 1$ a parabola, $e > 1$ a hyperbola — one definition for all three.|Toute conique (sauf le cercle) est l’ensemble des points dont la distance à un foyer vaut $e$ fois la distance à une droite, la directrice. $e < 1$ donne une ellipse, $e = 1$ une parabole, $e > 1$ une hyperbole — une seule définition pour les trois.|Toda cónica (salvo la circunferencia) es el conjunto de puntos cuya distancia a un foco es $e$ veces la distancia a una recta, la directriz. $e < 1$ da elipse, $e = 1$ parábola y $e > 1$ hipérbola: una definición para las tres.|円以外の 2 次曲線は、焦点までの距離が準線までの距離の $e$ 倍の点の集合。$e < 1$ 楕円、$e = 1$ 放物線、$e > 1$ 双曲線。|除圆外每种圆锥曲线都是到焦点距离等于到准线距离 $e$ 倍的点集。$e < 1$ 椭圆，$e = 1$ 抛物线，$e > 1$ 双曲线——一个定义统一三者。`,
      a: [Y(R`\frac{PF}{d(P, \ell)} = e`, { s: 30 }), EQ([-8, 6], [-6, 6]), IP('sqrt(x^2+y^2)=0.5*(4-x)', 'b'), IP('sqrt(x^2+y^2)=4-x'), PTL(0, 0, 'F'), VL2(4)] },
    { s: R`Focus at the origin, directrix $x = 4$: with $e = \tfrac12$ you get the blue ellipse, with $e = 1$ the yellow parabola. A point at distance 6 from the directrix of an $e = \tfrac12$ conic is 3 from the focus.|Foyer à l’origine, directrice $x = 4$ : avec $e = \tfrac12$ l’ellipse bleue, avec $e = 1$ la parabole jaune.|Foco en el origen, directriz $x = 4$: con $e = \tfrac12$ la elipse azul, con $e = 1$ la parábola amarilla.|焦点が原点、準線 $x = 4$：$e = \tfrac12$ で青い楕円、$e = 1$ で黄色い放物線。|焦点在原点、准线 $x = 4$：$e = \tfrac12$ 得蓝色椭圆，$e = 1$ 得黄色抛物线。`,
      a: [Y(R`PF = e\cdot d = \tfrac12\cdot 6 = 3`)] },
    { a: [F(R`e = 0.5,\quad d(P, \ell) = 6`)],
      ex: { k: 'val', v: '3', q: R`A conic has eccentricity 0.5. A point $P$ on it is 6 units from the directrix. How far is $P$ from the focus?|Une conique a une excentricité 0,5. Un point $P$ est à 6 unités de la directrice. À quelle distance est-il du foyer ?|Una cónica tiene excentricidad 0,5. Un punto $P$ de ella está a 6 de la directriz. ¿A qué distancia está del foco?|離心率 0.5 の曲線上の点 $P$ が準線から 6。焦点までの距離は？|离心率 0.5 的曲线上点 $P$ 到准线距离 6，它到焦点的距离是多少？`, sol: [R`PF = e\cdot d`, R`= 0.5\cdot 6 = 3`] } });

  lesson('Conics in general/Polar form', 'Polar equation of a conic|Équation polaire d’une conique|Ecuación polar de una cónica|2 次曲線の極方程式|圆锥曲线的极坐标方程',
    { s: R`With the focus at the pole and the directrix at distance $p$, the focus–directrix definition becomes $r = \tfrac{ep}{1 + e\cos\theta}$. This is how orbits are written: $r$ is smallest at $\theta = 0$ (perihelion) and largest at $\theta = \pi$ when $e < 1$.|Avec le foyer au pôle et la directrice à distance $p$, la définition foyer–directrice devient $r = \tfrac{ep}{1 + e\cos\theta}$. C’est ainsi qu’on écrit les orbites : $r$ est minimal en $\theta = 0$ (périhélie) et maximal en $\theta = \pi$ quand $e < 1$.|Con el foco en el polo y la directriz a distancia $p$, la definición foco–directriz queda $r = \tfrac{ep}{1 + e\cos\theta}$. Así se escriben las órbitas: $r$ es mínimo en $\theta = 0$ (perihelio) y máximo en $\theta = \pi$ si $e < 1$.|焦点を極、準線までの距離を $p$ とすると $r = \tfrac{ep}{1 + e\cos\theta}$。軌道はこの形：$e < 1$ なら $\theta = 0$ で最小（近日点）、$\theta = \pi$ で最大。|焦点在极点、准线距离为 $p$ 时，焦点–准线定义变为 $r = \tfrac{ep}{1 + e\cos\theta}$。轨道就这样写：$e < 1$ 时 $\theta = 0$ 处最近（近日点），$\theta = \pi$ 处最远。`,
      a: [Y(R`r = \frac{e\,p}{1 + e\cos\theta}`, { s: 30 }), EQ([-14, 6], [-10, 10]), IP('sqrt(x^2+y^2)+0.5x=6'), PTL(0, 0, 'F', 'b'), PTL(4, 0, 'r = 4'), PTL(-12, 0, 'r = 12')] },
    { s: R`$r = \tfrac{6}{1 + 0.5\cos\theta}$: $e = 0.5$, an ellipse. At $\theta = 0$: $r = 4$; at $\theta = \pi$: $r = \tfrac{6}{0.5} = 12$.|$r = \tfrac{6}{1 + 0{,}5\cos\theta}$ : ellipse ; $r = 4$ en $\theta = 0$, $r = 12$ en $\theta = \pi$.|$r = \tfrac{6}{1 + 0{,}5\cos\theta}$: elipse; $r = 4$ en $\theta = 0$ y $r = 12$ en $\theta = \pi$.|$r = 4$ と $12$。|$r = 4$ 与 $12$。`,
      a: [F(R`\theta = 0:\ r = \frac{6}{1.5} = 4`), Y(R`\theta = \pi:\ r = \frac{6}{0.5} = 12`)] },
    { a: [F(R`r = \frac{10}{1 + 0.5\cos\theta}`)],
      ex: { k: 'val', v: '20/3', q: R`For $r = \dfrac{10}{1 + 0.5\cos\theta}$, find the smallest distance from the focus (at $\theta = 0$).|Pour $r = \dfrac{10}{1 + 0{,}5\cos\theta}$, trouvez la plus petite distance au foyer (en $\theta = 0$).|Para $r = \dfrac{10}{1 + 0{,}5\cos\theta}$, halla la menor distancia al foco (en $\theta = 0$).|$r = \dfrac{10}{1 + 0.5\cos\theta}$ の焦点からの最小距離（$\theta = 0$）を求めよ。|对 $r = \dfrac{10}{1 + 0.5\cos\theta}$，求到焦点的最小距离（$\theta = 0$）。`, sol: [R`r(0) = \frac{10}{1.5}`, R`= \frac{20}{3} \approx 6.67`] } });

  Cheats.tutor('analytic', L);
})();
